window.PROTO = {"generated": "2026-09-28", "taxonomy": {"fields": [{"id": "score", "en": "Scores & Instructions", "zh": "乐谱与指令", "desc_en": "The artist writes instructions; other people carry them out, and each execution is the work. From telephone paintings and Fluxus event scores to Sol LeWitt's wall drawings.", "desc_zh": "艺术家写下指令，由别人去执行，每一次执行就是作品本身。从电话绘画、激浪派事件乐谱到索尔·勒维特的墙绘。", "subs": [{"id": "execution", "en": "Instructions for Execution", "zh": "交由他人执行的指令", "desc_en": "Works that exist as a set of instructions and are made, again and again, by assistants, owners or institutions.", "desc_zh": "以一组指令的形式存在、由助手、藏家或机构一次次制作出来的作品。"}, {"id": "event-scores", "en": "Event Scores & Fluxus", "zh": "事件乐谱与激浪派", "desc_en": "Short written scores for actions and events that anyone can perform.", "desc_zh": "写给行动和事件的简短乐谱，任何人都可以表演。"}, {"id": "public-instructions", "en": "Instructions for the Public", "zh": "写给公众的指令", "desc_en": "Instructions addressed to readers, visitors and strangers, who become the performers.", "desc_zh": "写给读者、观众和陌生人的指令，他们因此成为表演者。"}, {"id": "constraints", "en": "Constraints, Chance & Games", "zh": "约束、偶然与游戏", "desc_en": "Rule systems, constraints and chance procedures that generate outcomes the author does not control.", "desc_zh": "生成作者无法控制之结果的规则系统、约束和偶然程序。"}]}, {"id": "social", "en": "Social Protocols & Economies", "zh": "社会协议与另类经济", "desc_en": "Rules for groups, exchanges and contracts in physical space: social sculpture, performance protocols, mail-art networks and artist-made economies.", "desc_zh": "在物理空间中为群体、交换与契约设计的规则：社会雕塑、表演协议、邮件艺术网络，以及艺术家设计的经济。", "subs": [{"id": "collective-action", "en": "Social Sculpture & Collective Action", "zh": "社会雕塑与集体行动", "desc_en": "Works made by many people acting together under one rule: planting, walking, moving, gathering.", "desc_zh": "由许多人在同一条规则下共同行动而完成的作品：种树、行走、搬运、聚集。"}, {"id": "performance", "en": "Performance Protocols", "zh": "表演协议", "desc_en": "Performances where the audience's actions, bounded by the artist's rules, make the piece.", "desc_zh": "观众在艺术家规则之内的行动构成作品的表演。"}, {"id": "correspondence", "en": "Mail Art & Correspondence Networks", "zh": "邮件艺术与通信网络", "desc_en": "Artworks that travel through the post and grow as each recipient adds to them and sends them on.", "desc_zh": "通过邮政流转、每个收件人添加内容再寄出而不断生长的作品。"}, {"id": "economies", "en": "Contracts, Currencies & Exchange", "zh": "契约、货币与交换", "desc_en": "Artist-designed contracts, receipts, currencies and exchange rituals: the pre-blockchain ancestors of tokens and royalties.", "desc_zh": "艺术家设计的契约、收据、货币与交换仪式：代币和版税在区块链出现之前的前身。"}]}, {"id": "network", "en": "Network & Crowd Protocols", "zh": "网络与群体协议", "desc_en": "Rules posted to a network and played by thousands or millions of people: telematic art, crowdsourced works and collective online experiments.", "desc_zh": "发布到网络上、由成千上万人参与的规则：远程通信艺术、众包作品和集体网络实验。", "subs": [{"id": "telematic", "en": "Telematic & Early Network Art", "zh": "远程通信与早期网络艺术", "desc_en": "Works for modems, bulletin boards, robots and the early web that let distant participants act together.", "desc_zh": "为调制解调器、电子公告板、机器人和早期网络而作，让远方的参与者共同行动的作品。"}, {"id": "crowdsourced", "en": "Crowdsourced Works", "zh": "众包作品", "desc_en": "An assignment or task sent to a crowd; the collected responses are the work.", "desc_zh": "把一个任务派发给人群，收集到的回应就是作品。"}, {"id": "collective-games", "en": "Collective Canvases & Games", "zh": "集体画布与游戏", "desc_en": "Shared canvases, buttons and games where one simple rule meets a very large crowd.", "desc_zh": "共享画布、按钮和游戏：一条简单的规则遇上非常庞大的人群。"}, {"id": "open-infrastructure", "en": "Open Infrastructure & Commons", "zh": "开放基础设施与公地", "desc_en": "Artist-built infrastructures, file drops and commons that strangers maintain and use.", "desc_zh": "由艺术家搭建、由陌生人维护和使用的基础设施、文件投放点与公地。"}]}, {"id": "onchain", "en": "Smart-Contract Art", "zh": "智能合约艺术", "desc_en": "Artworks whose rules run in a smart contract: supply, burning, merging, transfer, taxes and co-authorship enforced on-chain, and shaped by what collectors do.", "desc_zh": "规则运行在智能合约里的作品：供应、销毁、合并、转移、税费与共同创作都在链上执行，并由藏家的行为塑造。", "subs": [{"id": "supply", "en": "Supply, Burn & Merge", "zh": "供应、销毁与合并", "desc_en": "Open editions, burning, merging and composites: the final form is set by how many people buy, burn or combine.", "desc_zh": "开放版数、销毁、合并与合成：最终形态取决于多少人购买、销毁或组合。"}, {"id": "ownership", "en": "Ownership & Transfer Rules", "zh": "所有权与转移规则", "desc_en": "Contracts that change what owning means: always for sale, must be passed on, dies if held, changes with its owner.", "desc_zh": "改变“拥有”含义的合约：永远在售、必须转手、持有即死亡、随持有者而改变。"}, {"id": "co-authored", "en": "Programmable & Co-authored Works", "zh": "可编程与共同创作的作品", "desc_en": "Works whose layers, parameters or worlds are written by their holders and by the community that builds on them.", "desc_zh": "图层、参数或世界由持有者和在其上继续创作的社区写成的作品。"}, {"id": "provenance", "en": "Early Tokens & Provenance", "zh": "早期代币与来源", "desc_en": "The first crypto-art tokens, registries and claim mechanics, before the 2021 boom.", "desc_zh": "2021 年热潮之前最早的加密艺术代币、登记簿和认领机制。"}]}, {"id": "autonomous", "en": "Autonomous Entities & DAOs", "zh": "自治实体与 DAO", "desc_en": "Artworks that own themselves, reproduce, or are governed by their community: self-owning forests, blockchain life forms, autonomous artists and art DAOs.", "desc_zh": "拥有自己、自我繁殖或由社区治理的作品：自我拥有的森林、区块链生命形式、自治艺术家与艺术 DAO。", "subs": [{"id": "self-owning", "en": "Self-owning Life & Nature", "zh": "自我拥有的生命与自然", "desc_en": "Forests, plants and life forms that hold their own money, sell their own output and reproduce through contracts.", "desc_zh": "持有自己的钱、出售自己的产出、通过合约繁殖的森林、植物与生命形式。"}, {"id": "autonomous-artists", "en": "Autonomous & Collective Artists", "zh": "自治与集体艺术家", "desc_en": "Artist identities run by a machine and a voting community, or licensed to the public under community rules.", "desc_zh": "由机器和投票社区运行、或在社区规则下向公众授权的艺术家身份。"}, {"id": "dao", "en": "DAOs & Collective Governance", "zh": "DAO 与集体治理", "desc_en": "Art projects where token holders vote, fund and decide: daily auctions, artist careers run by shareholders, collective purchases.", "desc_zh": "代币持有者投票、出资和决策的艺术项目：每日拍卖、由股东决定的艺术生涯、集体收购。"}]}, {"id": "theory", "en": "Theory & Texts", "zh": "理论与文本", "desc_en": "Books, essays and research programmes that define protocols, systems and participation in art.", "desc_zh": "界定艺术中的协议、系统与参与的书籍、文章与研究计划。", "subs": [{"id": "systems", "en": "Systems & Protocol Theory", "zh": "系统与协议理论", "desc_en": "Texts on systems aesthetics, protocols and control in networks.", "desc_zh": "关于系统美学、协议与网络中控制的文本。"}, {"id": "participation", "en": "Participation & Relational Art", "zh": "参与与关系艺术", "desc_en": "Texts on participatory, relational and social practice art.", "desc_zh": "关于参与式艺术、关系艺术和社会实践艺术的文本。"}, {"id": "crypto-theory", "en": "Crypto Art & Protocol Research", "zh": "加密艺术与协议研究", "desc_en": "Books, anthologies and research programmes on blockchain art, DAOs and protocols.", "desc_zh": "关于区块链艺术、DAO 与协议的书籍、文集和研究计划。"}]}], "mechanisms": [["instruction", "Instruction & score", "指令与乐谱"], ["participation", "Open participation", "开放参与"], ["constraint", "Rules & constraints", "规则与约束"], ["chance", "Chance & randomness", "偶然与随机"], ["circulation", "Circulation & passing on", "流转与传递"], ["exchange", "Market & exchange", "市场与交换"], ["currency", "Currency & value", "货币与价值"], ["contract", "Contract & certificate", "契约与证书"], ["scarcity", "Supply & scarcity", "供应与稀缺"], ["burn", "Burn & destruction", "销毁"], ["merge", "Merge & composite", "合并与合成"], ["co-authorship", "Co-authorship & derivatives", "共同创作与衍生"], ["governance", "Voting & governance", "投票与治理"], ["autonomy", "Self-ownership & autonomy", "自我拥有与自治"], ["time", "Time, decay & death", "时间、衰变与死亡"]], "substrates": [["text", "Text & paper", "文本与纸面"], ["body", "Bodies & space", "身体与空间"], ["post", "Post & mail", "邮政"], ["network", "Internet & platforms", "互联网与平台"], ["bitcoin", "Bitcoin & Counterparty", "比特币与 Counterparty"], ["ethereum", "Ethereum & L2s", "以太坊与二层网络"], ["tezos", "Tezos", "Tezos"], ["other-chain", "Other chains", "其他链"], ["ai", "AI & machine", "人工智能与机器"]], "kinds": [["artwork", "Artwork", "艺术作品"], ["score", "Score & instruction set", "乐谱与指令集"], ["series", "Series & collection", "系列与合集"], ["platform", "Platform & protocol", "平台与协议"], ["game", "Game & experiment", "游戏与实验"], ["organization", "DAO & organization", "DAO 与组织"], ["publication", "Book & essay", "书与文章"]], "collections": [{"id": "the-scores-project", "type": "survey", "en": "The Scores Project", "zh": "《乐谱计划》", "desc_en": "Open-access book edited by Michael Gallope, Natilee Harren and John Hicks (Getty Research Institute, 2025): eleven essays on experimental notation in music, art, poetry and dance, 1950–1975, from Feldman and Cage to Brecht, Knowles, Shiomi and Kaprow.", "desc_zh": "由 Michael Gallope、Natilee Harren 与 John Hicks 编辑的开放获取书籍（盖蒂研究所，2025）：十一篇文章讨论 1950—1975 年间音乐、艺术、诗歌与舞蹈中的实验记谱，从费尔德曼、凯奇到布雷希特、诺尔斯、盐见允枝子和卡普罗。", "url": "https://www.getty.edu/publications/scores/"}]}, "creators": [{"id": "pak", "links": {"x": "https://x.com/muratpak", "wikipedia": "https://en.wikipedia.org/wiki/Pak_(creator)"}, "connected_to": [], "name": "Pak", "kind": "anonymous", "role": "Anonymous digital artist and system designer", "bio": "Anonymous digital creator who also built the image-curating bot Archillect (2014). Between 2020 and 2022 Pak released a run of sales and contracts on Nifty Gateway, Sotheby's and their own sites: open editions, the ASH burn token, Lost Poets, Merge and Censored.", "why": "Pak turned sale formats and contract rules (open editions, burning, merging, one-token-per-wallet) into the artwork itself, so that what tens of thousands of buyers did is the finished piece.", "role_zh": "匿名数字艺术家、系统设计者", "bio_zh": "匿名数字创作者，2014 年做过图像策展机器人 Archillect。2020 至 2022 年间，Pak 在 Nifty Gateway、苏富比和自建网站上接连推出一系列发售与合约：开放版数、ASH 销毁代币、Lost Poets、Merge 和 Censored。", "why_zh": "Pak 把发售形式和合约规则（开放版数、销毁、合并、每个钱包只能持有一枚）本身做成作品，数万名买家的行为就是作品的最终形态。", "discovered_via": "seed", "work_count": 7}, {"id": "jack-butcher", "links": {"site": "https://jack.art", "x": "https://x.com/jackbutcher"}, "connected_to": [], "name": "Jack Butcher", "kind": "person", "role": "Conceptual artist, founder of Visualize Value", "bio": "Artist and founder of Visualize Value, known for works built from simple signs (a checkmark, a receipt, a trademark symbol). Since 2023 he has made editions whose images and supply are changed by collectors, often with developer Jalil Wahdatehagh.", "why": "Checks and Opepen made compositing-by-burning and holder opt-in into widely copied protocol forms, and his later works keep testing how a buyer's choice changes a shared work.", "role_zh": "观念艺术家，Visualize Value 创始人", "bio_zh": "艺术家，Visualize Value 创始人，作品常由简单符号构成（对勾、收据、商标符号）。自 2023 年起，他常与开发者 Jalil Wahdatehagh 合作，做出一系列由藏家改变图像与供应量的版数作品。", "why_zh": "Checks 和 Opepen 让“烧毁合成”和“持有者自愿加入”成为被广泛模仿的协议形式；他之后的作品继续检验买家的一次选择如何改变一件共有的作品。", "discovered_via": "seed", "work_count": 9}, {"id": "damien-hirst", "links": {"site": "https://www.damienhirst.com", "x": "https://x.com/hirst_official", "wikipedia": "https://en.wikipedia.org/wiki/Damien_Hirst"}, "connected_to": [], "name": "Damien Hirst", "kind": "person", "role": "Artist", "based": "London, UK", "bio": "British artist and a leading figure of the Young British Artists. With HENI he released The Currency (2021), his first NFT project.", "why": "The Currency made each buyer choose between a token and a painting, and destroyed whichever they rejected, so the final shape of 10,000 works was set by collectors.", "role_zh": "艺术家", "bio_zh": "英国艺术家，“英国青年艺术家”群体的代表人物。他与 HENI 合作推出了自己的第一个 NFT 项目 The Currency（2021）。", "why_zh": "The Currency 让每位买家在代币和画作之间二选一，未被选中的一方会被销毁，于是一万件作品最后的样子由藏家决定。", "based_zh": "伦敦，英国", "discovered_via": "seed", "work_count": 1}, {"id": "tom-sachs", "links": {"site": "https://www.tomsachsrocketfactory.com", "wikipedia": "https://en.wikipedia.org/wiki/Tom_Sachs"}, "connected_to": [], "name": "Tom Sachs", "kind": "person", "role": "Sculptor", "based": "New York, US", "bio": "American sculptor known for hand-built replicas of space programmes and branded objects. Rocket Factory (2021) is his NFT project, in which collectors assemble rockets from parts that his studio then builds and launches.", "why": "Rocket Factory ties an on-chain merge rule (three parts burned into one rocket) to a physical studio process and public launches.", "role_zh": "雕塑家", "bio_zh": "美国雕塑家，以手工复制太空计划和品牌物件著称。Rocket Factory（2021）是他的 NFT 项目：藏家用零件拼装火箭，再由他的工作室把火箭造出来并发射。", "why_zh": "Rocket Factory 把链上的合并规则（三个零件烧成一枚火箭）与工作室的实体制作和公开发射联系在一起。", "based_zh": "纽约，美国", "discovered_via": "seed", "work_count": 1}, {"id": "mitchell-f-chan", "links": {"site": "https://chan.gallery/", "x": "https://x.com/mitchellfchan", "github": "https://github.com/mitchellfchan"}, "connected_to": [], "name": "Mitchell F. Chan", "kind": "person", "role": "Artist and game maker", "bio": "Artist working with conceptual art, video games and smart contracts. His 2017 token work Digital Zones of Immaterial Pictorial Sensibility restages Yves Klein's receipt ritual in an Ethereum contract.", "why": "Digital Zones is an early smart contract that encodes an artist's sale ritual, including a burn function any holder can call.", "role_zh": "艺术家、游戏创作者", "bio_zh": "创作涉及观念艺术、电子游戏和智能合约的艺术家。他 2017 年的代币作品 Digital Zones of Immaterial Pictorial Sensibility 把伊夫·克莱因的收据仪式搬进以太坊合约。", "why_zh": "Digital Zones 是较早把艺术家的出售仪式写进智能合约的作品，其中包括任何持有者都能调用的销毁函数。", "discovered_via": "seed", "work_count": 1}, {"id": "sol-lewitt", "links": {"wikipedia": "https://en.wikipedia.org/wiki/Sol_LeWitt"}, "connected_to": [], "name": "Sol LeWitt", "kind": "person", "role": "Artist", "based": "New York, US", "bio": "American artist (1928–2007) central to Minimal and Conceptual art. His wall drawings exist as written instructions that assistants and institutions execute again and again.", "why": "He wrote the founding statements that treat the artwork as an idea that others carry out, the direct ancestor of protocol art.", "role_zh": "艺术家", "bio_zh": "美国艺术家（1928–2007），极简主义与观念艺术的核心人物。他的墙绘以书面指令的形式存在，由助手和机构一次次执行。", "why_zh": "他写下了把作品视为交由他人执行之观念的奠基性文字，是协议艺术的直接前身。", "based_zh": "纽约，美国", "discovered_via": "seed", "work_count": 2}, {"id": "jack-burnham", "links": {"wikipedia": "https://en.wikipedia.org/wiki/Jack_Burnham"}, "connected_to": [], "name": "Jack Burnham", "kind": "person", "role": "Artist, critic and curator", "based": "Chicago, US", "bio": "American artist and critic (1931–2019) who brought systems theory and cybernetics into art criticism in Artforum and curated the 1970 exhibition Software at the Jewish Museum.", "why": "He argued that art was moving from objects to systems of relations between people, machines and institutions.", "role_zh": "艺术家、评论家与策展人", "bio_zh": "美国艺术家与评论家（1931–2019），在《Artforum》上把系统论和控制论引入艺术批评，并于 1970 年在犹太博物馆策划展览 Software。", "why_zh": "他提出艺术正从物体转向由人、机器和机构之间关系构成的系统。", "based_zh": "芝加哥，美国", "discovered_via": "seed", "work_count": 2}, {"id": "roy-ascott", "links": {"wikipedia": "https://en.wikipedia.org/wiki/Roy_Ascott"}, "connected_to": [], "name": "Roy Ascott", "kind": "person", "role": "Artist and theorist of telematic art", "based": "London, UK", "bio": "British artist and educator (born 1934) who developed cybernetic art teaching in the 1960s and telematic network artworks from the late 1970s.", "why": "He framed networked art as distributed authorship, where meaning is made by many participants connected through a network.", "role_zh": "艺术家、远程通信艺术理论家", "bio_zh": "英国艺术家与教育者（1934 年生），1960 年代发展出控制论式的艺术教学，1970 年代末起创作远程通信网络作品。", "why_zh": "他把网络艺术阐释为分布式创作：意义由通过网络相连的众多参与者共同生成。", "based_zh": "伦敦，英国", "discovered_via": "seed", "work_count": 1}, {"id": "benjamin-buchloh", "links": {"wikipedia": "https://en.wikipedia.org/wiki/Benjamin_Buchloh"}, "connected_to": ["sol-lewitt"], "name": "Benjamin H. D. Buchloh", "kind": "person", "role": "Art historian", "based": "Cambridge, MA, US", "bio": "German art historian (born 1941) and editor of October, known for his histories of Conceptual art and postwar European art.", "why": "He described Conceptual art as an 'aesthetic of administration': art made of certificates, lists, contracts and bureaucratic procedures.", "role_zh": "艺术史学者", "bio_zh": "德国艺术史学者（1941 年生），《October》编辑，以观念艺术和战后欧洲艺术研究著称。", "why_zh": "他把观念艺术描述为一种“管理美学”：由证书、清单、契约和官僚程序构成的艺术。", "based_zh": "马萨诸塞州剑桥，美国", "discovered_via": "sol-lewitt", "work_count": 1}, {"id": "alexander-galloway", "links": {"site": "http://cultureandcommunication.org/galloway/", "wikipedia": "https://en.wikipedia.org/wiki/Alexander_R._Galloway"}, "connected_to": ["eugene-thacker"], "name": "Alexander R. Galloway", "kind": "person", "role": "Media theorist and programmer", "based": "New York, US", "bio": "American media theorist at New York University and a founding member of the software art collective RSG (Radical Software Group).", "why": "His book Protocol gave art and media theory its working definition of protocol as the form control takes in decentralized networks.", "role_zh": "媒介理论家、程序员", "bio_zh": "美国媒介理论家，任教于纽约大学，软件艺术团体 RSG（Radical Software Group）的创始成员。", "why_zh": "他的《Protocol》一书为艺术与媒介理论提供了“协议”的基本定义：协议是控制在去中心化网络中的存在形式。", "based_zh": "纽约，美国", "discovered_via": "seed", "work_count": 2}, {"id": "eugene-thacker", "links": {"wikipedia": "https://en.wikipedia.org/wiki/Eugene_Thacker"}, "connected_to": ["alexander-galloway"], "name": "Eugene Thacker", "kind": "person", "role": "Philosopher and media theorist", "based": "New York, US", "bio": "American philosopher and writer, professor at The New School, who has written on biotechnology, networks and the philosophy of horror.", "why": "With Galloway he wrote The Exploit, a theory of how networks are controlled and how they can be resisted from inside their protocols.", "role_zh": "哲学家、媒介理论家", "bio_zh": "美国哲学家与作家，任教于新学院（The New School），著述涉及生物技术、网络与恐怖哲学。", "why_zh": "他与 Galloway 合著《The Exploit》，讨论网络如何被控制，以及如何从协议内部进行抵抗。", "based_zh": "纽约，美国", "discovered_via": "alexander-galloway", "work_count": 1}, {"id": "florian-cramer", "links": {}, "connected_to": [], "name": "Florian Cramer", "kind": "person", "role": "Writer and researcher on code and culture", "based": "Rotterdam, NL", "bio": "German writer and researcher on literature, computing and media culture, long associated with the Piet Zwart Institute and Willem de Kooning Academy in Rotterdam.", "why": "He traced the idea of executable instructions from magic formulas and combinatory poetry to software, linking scores to code.", "role_zh": "代码与文化研究者、作家", "bio_zh": "德国作家与研究者，研究文学、计算与媒介文化，长期任职于鹿特丹 Piet Zwart Institute 和 Willem de Kooning 学院。", "why_zh": "他追溯了“可执行指令”的观念：从咒语和组合诗歌一直到软件，把乐谱与代码联系起来。", "based_zh": "鹿特丹，荷兰", "discovered_via": "seed", "work_count": 1}, {"id": "nicolas-bourriaud", "links": {"wikipedia": "https://en.wikipedia.org/wiki/Nicolas_Bourriaud"}, "connected_to": ["claire-bishop"], "name": "Nicolas Bourriaud", "kind": "person", "role": "Curator and critic", "based": "Paris, FR", "bio": "French curator and writer, co-founder of the Palais de Tokyo, who named the 1990s tendency of artworks built from social encounters 'relational aesthetics'.", "why": "He made human relations and the situations an artist sets up the recognised material of contemporary art.", "role_zh": "策展人、评论家", "bio_zh": "法国策展人与作家，东京宫（Palais de Tokyo）联合创办人，把 1990 年代以社交相遇为材料的艺术倾向命名为“关系美学”。", "why_zh": "他让人际关系以及艺术家设定的情境成为当代艺术公认的材料。", "based_zh": "巴黎，法国", "discovered_via": "seed", "work_count": 1}, {"id": "claire-bishop", "links": {"wikipedia": "https://en.wikipedia.org/wiki/Claire_Bishop"}, "connected_to": ["grant-kester", "nicolas-bourriaud"], "name": "Claire Bishop", "kind": "person", "role": "Art historian and critic", "based": "New York, US", "bio": "British art historian, professor at the CUNY Graduate Center, who writes on participatory art, installation and performance.", "why": "She wrote the standard history and critique of participatory art, asking what audiences actually do and who sets the rules.", "role_zh": "艺术史学者、评论家", "bio_zh": "英国艺术史学者，任教于纽约市立大学研究生中心，研究参与式艺术、装置与表演。", "why_zh": "她写出了参与式艺术的标准历史与批评，追问观众实际做了什么、规则由谁设定。", "based_zh": "纽约，美国", "discovered_via": "seed", "work_count": 2}, {"id": "grant-kester", "links": {}, "connected_to": ["claire-bishop"], "name": "Grant Kester", "kind": "person", "role": "Art historian", "based": "San Diego, US", "bio": "American art historian at the University of California, San Diego, who studies collaborative and socially engaged art.", "why": "He described 'dialogical art', where the work is a structured conversation between an artist and a community.", "role_zh": "艺术史学者", "bio_zh": "美国艺术史学者，任教于加州大学圣地亚哥分校，研究协作式与社会介入式艺术。", "why_zh": "他提出“对话性艺术”：作品是艺术家与社区之间一场有结构的对话。", "based_zh": "圣地亚哥，美国", "discovered_via": "claire-bishop", "work_count": 1}, {"id": "hans-ulrich-obrist", "links": {"wikipedia": "https://en.wikipedia.org/wiki/Hans_Ulrich_Obrist"}, "connected_to": [], "name": "Hans Ulrich Obrist", "kind": "person", "role": "Curator", "based": "London, UK", "bio": "Swiss curator, artistic director of the Serpentine Galleries in London, who started the instruction-based exhibition do it in 1993.", "why": "do it turned the exhibition into a set of artists' instructions that any institution or reader can carry out.", "role_zh": "策展人", "bio_zh": "瑞士策展人，伦敦蛇形画廊艺术总监，1993 年发起以指令为基础的展览 do it。", "why_zh": "do it 把展览变成一组艺术家指令，任何机构或读者都能执行。", "based_zh": "伦敦，英国", "discovered_via": "seed", "work_count": 1}, {"id": "ruth-catlow", "links": {"site": "https://ruthcatlow.net/", "wikipedia": "https://en.wikipedia.org/wiki/Ruth_Catlow"}, "connected_to": ["marc-garrett", "penny-rafferty", "primavera-de-filippi"], "name": "Ruth Catlow", "kind": "person", "role": "Artist, curator and co-founder of Furtherfield", "based": "London, UK", "bio": "British artist and curator, co-founder and co-artistic director of Furtherfield, and a leading researcher of blockchain, DAOs and the arts.", "why": "Her edited books set the agenda for artists treating blockchains and DAOs as tools to redesign how art is owned and governed.", "role_zh": "艺术家、策展人，Furtherfield 联合创办人", "bio_zh": "英国艺术家与策展人，Furtherfield 联合创办人及联合艺术总监，是区块链、DAO 与艺术领域的重要研究者。", "why_zh": "她主编的书为“艺术家用区块链和 DAO 重新设计艺术的所有与治理”设定了议程。", "based_zh": "伦敦，英国", "discovered_via": "seed", "work_count": 2}, {"id": "marc-garrett", "links": {}, "connected_to": ["ruth-catlow"], "name": "Marc Garrett", "kind": "person", "role": "Artist, writer and co-founder of Furtherfield", "based": "London, UK", "bio": "British artist, writer and curator who co-founded the London art and technology organisation Furtherfield with Ruth Catlow in 1996.", "why": "He co-edited the first book on what blockchains mean for art production and distribution.", "role_zh": "艺术家、作家，Furtherfield 联合创办人", "bio_zh": "英国艺术家、作家与策展人，1996 年与 Ruth Catlow 共同创办伦敦艺术与技术机构 Furtherfield。", "why_zh": "他参与主编了第一本讨论区块链对艺术生产与传播意味着什么的书。", "based_zh": "伦敦，英国", "discovered_via": "ruth-catlow", "work_count": 1}, {"id": "penny-rafferty", "links": {}, "connected_to": ["ruth-catlow"], "name": "Penny Rafferty", "kind": "person", "role": "Writer and researcher", "bio": "Writer and researcher working on art, blockchain and DAOs, and co-editor of Radical Friends with Ruth Catlow.", "why": "She helped shift the art-and-blockchain debate from NFTs toward DAOs as a way for artists to organise.", "role_zh": "作家、研究者", "bio_zh": "研究艺术、区块链与 DAO 的作家和研究者，与 Ruth Catlow 共同主编《Radical Friends》。", "why_zh": "她推动艺术与区块链的讨论从 NFT 转向 DAO，把 DAO 视为艺术家自我组织的方式。", "discovered_via": "ruth-catlow", "work_count": 1}, {"id": "rhea-myers", "links": {"site": "https://rhea.art/"}, "connected_to": ["ruth-catlow"], "name": "Rhea Myers", "kind": "person", "role": "Artist, writer and hacker", "bio": "Artist, hacker and writer who has made blockchain artworks since 2011, including early smart-contract works and conceptual pieces about value and ownership.", "why": "One of the first artists to treat smart contracts as a conceptual-art medium, and a sharp critic of crypto culture.", "role_zh": "艺术家、作家、黑客", "bio_zh": "艺术家、黑客与作家，自 2011 年起创作区块链艺术，包括早期的智能合约作品以及关于价值与所有权的观念作品。", "why_zh": "她是最早把智能合约当作观念艺术媒介的艺术家之一，也是加密文化的尖锐批评者。", "discovered_via": "seed", "work_count": 1}, {"id": "kei-kreutler", "links": {"site": "https://keikreutler.net/"}, "connected_to": [], "name": "Kei Kreutler", "kind": "person", "role": "Artist, writer and co-founder of Gnosis Guild", "bio": "Artist and writer working on decentralized organisations, co-founder of Gnosis Guild, which builds open tools for DAOs.", "why": "Her essay places DAOs in a longer history of cooperatives and game guilds, giving art DAOs a lineage beyond crypto.", "role_zh": "艺术家、作家，Gnosis Guild 联合创办人", "bio_zh": "研究去中心化组织的艺术家与作家，Gnosis Guild 联合创办人，该团队为 DAO 开发开源工具。", "why_zh": "她的文章把 DAO 放进合作社和游戏公会的长历史里，为艺术 DAO 提供了加密之外的谱系。", "discovered_via": "seed", "work_count": 1}, {"id": "primavera-de-filippi", "links": {"wikipedia": "https://en.wikipedia.org/wiki/Primavera_De_Filippi"}, "connected_to": ["aaron-wright", "ruth-catlow"], "name": "Primavera De Filippi", "kind": "person", "role": "Legal scholar and artist", "based": "Paris, FR", "bio": "Researcher at the CNRS in Paris and faculty associate at Harvard's Berkman Klein Center, who studies blockchain governance and makes artworks such as the blockchain-based flower Plantoid.", "why": "She works on both sides of protocol art: the law of self-executing code and artworks that own and reproduce themselves.", "role_zh": "法学学者、艺术家", "bio_zh": "巴黎法国国家科学研究中心（CNRS）研究员、哈佛 Berkman Klein 中心研究员，研究区块链治理，并创作了基于区块链的机械花 Plantoid 等作品。", "why_zh": "她同时处在协议艺术的两端：研究自动执行代码的法律，也创作能拥有并繁殖自己的作品。", "based_zh": "巴黎，法国", "discovered_via": "seed", "work_count": 1}, {"id": "aaron-wright", "links": {}, "connected_to": ["primavera-de-filippi"], "name": "Aaron Wright", "kind": "person", "role": "Legal scholar", "based": "New York, US", "bio": "American law professor at Cardozo School of Law, where he directs the Tech Startup Clinic, and co-author of Blockchain and the Law.", "why": "He helped define how smart contracts and DAOs relate to legal rules, the frame artists now use for contract-based works.", "role_zh": "法学学者", "bio_zh": "美国法学教授，任教于 Cardozo 法学院并主持其科技创业法律诊所，《Blockchain and the Law》合著者。", "why_zh": "他帮助界定智能合约与 DAO 同法律规则的关系，这正是艺术家创作合约作品时所依托的框架。", "based_zh": "纽约，美国", "discovered_via": "primavera-de-filippi", "work_count": 1}, {"id": "amy-whitaker", "links": {}, "connected_to": [], "name": "Amy Whitaker", "kind": "person", "role": "Researcher in arts entrepreneurship", "based": "New York, US", "bio": "American writer and professor at New York University's Steinhardt School who studies art markets, artists' equity and blockchain.", "why": "She mapped the early uses of blockchain in the arts and proposed shared-equity models that give artists a stake in resales.", "role_zh": "艺术创业研究者", "bio_zh": "美国作家，纽约大学 Steinhardt 学院教授，研究艺术市场、艺术家权益与区块链。", "why_zh": "她梳理了区块链在艺术中的早期用途，并提出让艺术家分享转售收益的共同权益模式。", "based_zh": "纽约，美国", "discovered_via": "seed", "work_count": 1}, {"id": "summer-of-protocols", "links": {"site": "https://summerofprotocols.com/"}, "connected_to": ["venkatesh-rao"], "name": "Summer of Protocols", "kind": "collective", "role": "Research programme on protocols", "bio": "Research programme commissioned by the Ethereum Foundation in late 2022 that brought researchers, artists and engineers together to study protocols across fields; it ran seasons from 2023 to 2025.", "why": "It built a shared vocabulary for protocols as a designable, cultural form, the ground on which 'protocolized' art and design now stand.", "role_zh": "协议研究计划", "bio_zh": "由以太坊基金会于 2022 年底委托发起的研究计划，把研究者、艺术家和工程师聚在一起跨领域研究协议，2023 至 2025 年每年举办一季。", "why_zh": "它建立了一套把协议视为可设计的文化形式的共同词汇，是“协议化”艺术与设计的理论基础。", "discovered_via": "seed", "work_count": 2}, {"id": "venkatesh-rao", "links": {"site": "https://ribbonfarm.com/", "wikipedia": "https://en.wikipedia.org/wiki/Venkatesh_Rao"}, "connected_to": ["summer-of-protocols"], "name": "Venkatesh Rao", "kind": "person", "role": "Writer and consultant", "bio": "Indian-American writer, founder of the blog Ribbonfarm, and a director of the Summer of Protocols research programme.", "why": "He led the effort to treat protocols as a general subject of study, from traffic rules to blockchains.", "role_zh": "作家、顾问", "bio_zh": "印度裔美国作家，博客 Ribbonfarm 创办人，Summer of Protocols 研究计划的负责人之一。", "why_zh": "他主导把协议作为一个普遍研究对象来看待，从交通规则到区块链。", "discovered_via": "summer-of-protocols", "work_count": 2}, {"id": "jacob-horne", "links": {"site": "https://jacob.energy/", "x": "https://x.com/js_horne"}, "connected_to": [], "name": "Jacob Horne", "kind": "person", "role": "Co-founder of Zora", "bio": "American entrepreneur and co-founder of Zora, an onchain protocol and platform for minting and collecting media.", "why": "His essay Hyperstructures named the idea of protocols that run without their makers, a design goal for many onchain art systems.", "role_zh": "Zora 联合创办人", "bio_zh": "美国创业者，Zora 联合创办人；Zora 是一个用于铸造和收藏媒体的链上协议与平台。", "why_zh": "他的文章《Hyperstructures》提出了“脱离创造者也能持续运行的协议”这一概念，成为许多链上艺术系统的设计目标。", "discovered_via": "seed", "work_count": 1}, {"id": "malte-rauch", "links": {}, "connected_to": [], "name": "Malte Rauch", "kind": "person", "role": "Curator and writer", "bio": "Curator and writer on blockchain art who has worked with Bright Moments and the Verse platform, and wrote the essay for the contract show World Computer Sculpture Garden.", "why": "His essay gives one of the clearest definitions of protocol art as art concerned with the rules that precede and define a computing environment.", "role_zh": "策展人、作家", "bio_zh": "研究区块链艺术的策展人与作家，曾与 Bright Moments 和 Verse 平台合作，为合约展览 World Computer Sculpture Garden 撰写文章。", "why_zh": "他的文章对协议艺术给出了最清晰的定义之一：关注先于并界定计算环境之规则的艺术。", "discovered_via": "seed", "work_count": 1}, {"id": "botao-amber-hu", "links": {"site": "https://botao.hu/"}, "connected_to": [], "name": "Botao Amber Hu", "kind": "person", "role": "Designer and researcher, Reality Design Lab", "bio": "Designer and HCI researcher who leads Reality Design Lab and publishes on protocol art, speculative design, mixed reality and decentralized AI.", "why": "Author of the first peer-reviewed study that defines protocol art through a close reading of Pak's smart-contract works.", "role_zh": "设计师、研究者，Reality Design Lab", "bio_zh": "设计师与人机交互研究者，主持 Reality Design Lab，发表关于协议艺术、思辨设计、混合现实与去中心化 AI 的研究。", "why_zh": "他撰写了第一篇通过细读 Pak 的智能合约作品来界定协议艺术的同行评审论文。", "discovered_via": "seed", "work_count": 2}, {"id": "mat-dryhurst", "links": {"wikipedia": "https://en.wikipedia.org/wiki/Mat_Dryhurst"}, "connected_to": [], "name": "Mat Dryhurst", "kind": "person", "role": "Artist, musician and researcher", "based": "Berlin, DE", "bio": "Artist and researcher who works with Holly Herndon on AI and voice projects such as Holly+, and co-founded Spawning, which builds consent tools for AI training data.", "why": "He argues that artists should design protocols directly, as 'executable critique', rather than make work inside platforms.", "role_zh": "艺术家、音乐人、研究者", "bio_zh": "艺术家与研究者，与 Holly Herndon 合作 Holly+ 等 AI 与声音项目，并联合创办 Spawning，为 AI 训练数据开发授权同意工具。", "why_zh": "他主张艺术家应当直接设计协议，作为“可执行的批判”，而不是在平台内部做作品。", "based_zh": "柏林，德国", "discovered_via": "seed", "work_count": 1}, {"id": "vera-list-center", "links": {"site": "https://www.veralistcenter.org/", "wikipedia": "https://en.wikipedia.org/wiki/Vera_List_Center_for_Art_and_Politics"}, "connected_to": [], "name": "Vera List Center for Art and Politics", "kind": "collective", "role": "Research center at The New School", "based": "New York, US", "bio": "Research and public programme centre at The New School in New York that works on the relation between art and politics through seasonal focus themes.", "why": "Its multi-year focus theme and book As for Protocols treat protocols as shared social forms that artists can rewrite.", "role_zh": "新学院下属研究中心", "bio_zh": "纽约新学院（The New School）下属的研究与公共项目中心，以分季主题研究艺术与政治的关系。", "why_zh": "它多年的焦点主题和《As for Protocols》一书把协议视为艺术家可以重写的共享社会形式。", "based_zh": "纽约，美国", "discovered_via": "seed", "work_count": 1}], "works": [{"id": "jack-butcher--credits", "creator_ids": ["jack-butcher"], "title": "Credits", "year": 2026, "field": "onchain", "sub": "supply", "mechanisms": ["burn", "merge", "currency"], "substrate": "network", "kind": "series", "description": "Each eligible $8 payment through X Money becomes a Credit, an image of four 8 × 8 CMYK grids derived from the transaction ID. Holders can burn 80 Credits to compose a Statement and overprint Statements onto each other.", "description_zh": "每一笔符合条件、通过 X Money 支付的 8 美元都会生成一个 Credit：由交易编号生成的四个 8 × 8 CMYK 网格。持有者可以销毁 80 个 Credit 组成一个 Statement，再把 Statement 相互叠印。", "idea_en": "Payment records as printing plates: collectors spend trust (credits) to make fewer, denser prints.", "idea_zh": "把付款记录当作印版：藏家花掉“信用”，换来更少、更厚重的印张。", "protocol": "A transaction ID is hashed (SHA-256) into 256 bits, split into cyan, magenta, yellow and black 64-bit grids; the timestamp selects which layers show. Burning 80 Credits composes a Statement, one Credit per cell. Overprinting one Statement onto another burns the top one and multiplies the inks. Statements are capped at 1,526 and the minimum is 1.", "protocol_zh": "交易编号经 SHA-256 哈希得到 256 位，分成青、品红、黄、黑四个 64 位网格；时间戳决定显示哪些层。销毁 80 个 Credit 组成一个 Statement，每个 Credit 填一个格子。把一个 Statement 叠印到另一个上，上层被销毁，油墨相乘。Statement 最多 1,526 个，最少 1 个。", "collective": "Credits are being issued from X Money payments; Statement assembly opens on 1 October 2026, so how far collectors will compress the supply is not yet known.", "collective_zh": "Credit 正随着 X Money 付款不断生成；Statement 的组装于 2026 年 10 月 1 日开放，藏家会把供应压缩到什么程度尚不可知。", "keywords": ["X Money", "CMYK", "overprint", "Statement", "SHA-256", "burn"], "images": ["https://jack.art/credits/assets/art-0.svg", "https://jack.art/credits/assets/credit-0.svg"], "source_url": "https://jack.art/credits", "video": {}, "paper": {}, "also": []}, {"id": "jack-butcher--economy-of-words", "creator_ids": ["jack-butcher"], "title": "Economy of Words", "year": 2026, "field": "onchain", "sub": "ownership", "mechanisms": ["exchange", "scarcity", "contract"], "substrate": "ethereum", "kind": "series", "description": "A card for each of the 2,048 words of the BIP39 seed-phrase list, each graded by a formula and sold in its own auction; winners then chose whether the card would exist as a physical graded card or as a synthetic card on Ethereum.", "description_zh": "为 BIP39 助记词表的 2,048 个单词各做一张卡片，按公式评级，逐一拍卖；得标者再选择这张卡以实体评级卡还是以太坊上的合成卡的形式存在。", "idea_en": "Three hierarchies compete over the same words: a mechanical grade, what bidders pay, and the material form each winner picks.", "idea_zh": "三种等级在同一批单词上竞争：机械评级、竞价者愿付的价格、以及每位得标者选择的材质形态。", "protocol": "Grades (10 bands) come from word length, initial letter, letter values and list position. Each auction opened at $1 and ran 20 hours 48 minutes, extended by late bids. Winners had 2,048 minutes after closing to choose physical or synthetic; the choice then locked.", "protocol_zh": "评级（10 档）由单词长度、首字母、字母分值和在列表中的位置计算。每场拍卖以 1 美元起拍，持续 20 小时 48 分钟，临近结束有出价则延时。得标者在结拍后 2,048 分钟内选择实体或合成形态，之后不可更改。", "collective": "The studio's collector board ranks 331 holders of the 2,048 words by spend and shows the physical/synthetic split; final totals are not yet published.", "collective_zh": "工作室的藏家榜按花费列出 2,048 个单词的 331 位持有者，并显示实体与合成的比例；最终总额尚未公布。", "keywords": ["BIP39", "auction", "grading", "physical or digital", "cards"], "images": ["https://jack.art/eow-hero.webp", "https://jack.art/eow-ui-collectors.webp"], "source_url": "https://jack.art/economy-of-words", "video": {}, "paper": {}, "also": []}, {"id": "jack-butcher--know-your-collector", "creator_ids": ["jack-butcher"], "title": "Know Your Collector", "year": 2026, "field": "onchain", "sub": "co-authored", "mechanisms": ["co-authorship", "participation"], "substrate": "ethereum", "kind": "series", "description": "A collection of synthetic portraits in which each participant tuned an invented face (seed, pose, expression, lighting, bands) and publicly linked their chosen configuration to their X account.", "description_zh": "一组合成肖像：每位参与者调节一张虚构的脸（种子、姿态、表情、光线、条纹），并把自己选定的配置公开绑定到自己的 X 账号。", "idea_en": "Reverse KYC: instead of an institution identifying the customer, each collector chooses the invented face that will stand for them.", "idea_zh": "反向的 KYC：不是机构识别客户，而是每位藏家挑选一张代表自己的虚构面孔。", "protocol": "Access came through a patron edition. Each participant configured a portrait rendered with Google's GNM head model, kept one configuration, and posted a public verification code from an established X account, linking an account to a choice.", "protocol_zh": "参与资格来自一个赞助版数。每位参与者用谷歌 GNM 头部模型生成并调整肖像，保留一种配置，再从一个已有的 X 账号发布公开验证码，把账号与选择绑定。", "collective": "The studio's 19 August 2026 export holds 565 saved portraits, each a collector's choice rather than a likeness.", "collective_zh": "工作室 2026 年 8 月 19 日的导出记录共有 565 幅已保存的肖像，每一幅都是一位藏家的选择，而非本人相貌。", "keywords": ["KYC", "synthetic portraits", "GNM", "verification", "identity"], "images": ["https://jack.art/kyc/grid.png"], "source_url": "https://jack.art/kyc", "video": {}, "paper": {}, "also": []}, {"id": "jack-butcher--work-luck-play", "creator_ids": ["jack-butcher"], "title": "Work, Luck, Play", "year": 2026, "field": "social", "sub": "economies", "also": ["onchain"], "mechanisms": ["exchange", "chance", "circulation"], "substrate": "body", "kind": "game", "description": "Silver sculptures and a trading game presented by Silk at Art Basel Hong Kong (March 2026): a dice roll gave each participant six resin dice, and participants traded with each other to complete a set of one to six.", "description_zh": "由 Silk 在香港巴塞尔艺博会（2026 年 3 月）呈现的银雕塑与交换游戏：掷一次普通骰子决定每位参与者得到哪六颗树脂骰子，参与者相互交换，凑齐一到六的整套。", "idea_en": "Separate effort, fixed luck and choices made together: the finished set can only come from trading with strangers.", "idea_zh": "把努力、注定的运气和共同的选择分开：完整的一套只能靠与陌生人交换得来。", "protocol": "A roll of ordinary dice decided which six resin dice a visitor received (Luck's dice carry one number on every face). Participants could trade to assemble 1 through 6 and return for a signed set, or keep an incomplete combination. An online rolling system on Ethereum and a token-burning route to claim a silver die ran alongside.", "protocol_zh": "掷一次普通骰子，决定观众拿到哪六颗树脂骰子（Luck 系列的骰子每一面都是同一个数字）。参与者可以交换凑齐 1 到 6，回来换一套签名套装，也可以保留不完整的组合。同时还有以太坊上的线上掷骰系统，以及通过销毁代币领取银骰子的途径。", "collective": "Fair visitors traded dice among themselves to complete sets, and an accumulating archive ('Luckiest') recorded the rolls; no participant counts have been published.", "collective_zh": "艺博会观众彼此交换骰子来凑齐整套，一个不断累积的档案（“Luckiest”）记录下每次掷骰；参与人数尚未公布。", "keywords": ["dice", "trading", "Art Basel Hong Kong", "Silk", "Asprey Studio", "burn to claim"], "images": ["https://jack.art/play/wlp-thumb.png", "https://jack.art/play/play-dice.webp"], "source_url": "https://jack.art/work-luck-play", "video": {}, "paper": {}}, {"id": "vera-list-center--as-for-protocols", "creator_ids": ["vera-list-center"], "title": "As for Protocols", "year": 2025, "field": "theory", "sub": "systems", "also": ["social"], "mechanisms": ["constraint", "participation"], "substrate": "text", "kind": "publication", "description": "Open-access book edited by Re'al Christian, Carin Kuoni and Eriola Pira (Vera List Center for Art and Politics and Amherst College Press, 2025) with contributions by 24 artists, writers, scholars, musicians, architects and scientists on protocols.", "description_zh": "由 Re'al Christian、Carin Kuoni 与 Eriola Pira 主编的开放获取图书（Vera List 艺术与政治中心与 Amherst College Press，2025），24 位艺术家、作家、学者、音乐人、建筑师和科学家撰文讨论协议。", "idea_en": "Protocols are social forms of care and relation, and artists can write more equitable ones.", "idea_zh": "协议是关于关怀与关系的社会形式，艺术家可以写出更公平的协议。", "protocol": "The book frames protocols as 'systems of language that regulate how we relate to each other' and to technologies, and asks contributors to propose new protocols that are inclusive and equitable.", "protocol_zh": "该书把协议理解为“规范我们如何彼此相处”以及如何与技术相处的语言系统，并邀请撰稿人提出包容而公平的新协议。", "collective": "Contributors include Raven Chacon, Carolina Caycedo, Mary Maggic, Shannon Mattern, Rasheedah Phillips, Leanne Betasamosake Simpson, Ultra-red and Underground Resistance, drawn from the Center's multi-year focus theme.", "collective_zh": "撰稿人包括 Raven Chacon、Carolina Caycedo、Mary Maggic、Shannon Mattern、Rasheedah Phillips、Leanne Betasamosake Simpson、Ultra-red 和 Underground Resistance，来自该中心多年的焦点主题研究。", "keywords": ["protocols", "Vera List Center", "Amherst College Press", "open access", "social practice"], "images": ["https://veralistcenter.wpenginepowered.com/wp-content/uploads/2025/03/AfP_final-cover.png"], "paper": {"url": "https://www.fulcrum.org/concern/monographs/3t945t729", "venue": "Vera List Center for Art and Politics / Amherst College Press, 2025", "title": "As for Protocols"}, "source_url": "https://www.veralistcenter.org/publications/as-for-protocols", "video": {}}, {"id": "jack-butcher--full-set", "creator_ids": ["jack-butcher"], "title": "Full Set", "year": 2025, "field": "onchain", "sub": "supply", "mechanisms": ["scarcity", "participation", "constraint"], "substrate": "ethereum", "kind": "series", "description": "Twenty-seven editions on an Ethereum layer 2 (with Rodeo). The first 26 images were replaced by one shared grid, and the 27th edition decided whether that change would last.", "description_zh": "在以太坊二层网络上发行（与 Rodeo 合作）的 27 个版数。前 26 张图像被替换成一张共享网格，而第 27 个版数决定这一改变能否保留。", "idea_en": "A single collecting threshold that can rewrite, or undo, what earlier buyers own.", "idea_zh": "一个收藏门槛，可以改写——也可以撤销——早先买家手中的作品。", "protocol": "On 10 January 2025 Butcher announced that if token 27 sold more than 159,300 editions (the combined count of the first 26), the network grid would remain the artwork; otherwise the first 26 would revert to their original images.", "protocol_zh": "2025 年 1 月 10 日，Butcher 宣布：如果第 27 号代币的售出数量超过 159,300（前 26 个的总和），网格就成为最终作品；否则前 26 个将恢复原来的图像。", "collective": "Buyers of token 27 decided the outcome for holders of all earlier works. A progress post followed on 11 January, and the studio catalogue reports that the threshold was passed (the crossing transaction has not been published).", "collective_zh": "第 27 号代币的买家替所有早期作品的持有者决定了结果。1 月 11 日有进度帖，工作室图录称门槛已被越过（越过门槛的那笔交易尚未公开）。", "keywords": ["threshold", "mutable metadata", "Rodeo", "layer 2", "grid"], "images": ["https://images.squarespace-cdn.com/content/v1/6547fdfa39dde777e76d89b5/1737348451051-J8FGEY2AZNQTBMQAGJ6E/thumb.png"], "source_url": "https://jack.art/full-set", "video": {}, "paper": {}, "also": []}, {"id": "mat-dryhurst--protocol-art", "creator_ids": ["mat-dryhurst"], "title": "Protocol Art", "year": 2025, "field": "theory", "sub": "crypto-theory", "mechanisms": ["governance", "co-authorship", "constraint"], "substrate": "text", "kind": "publication", "description": "Lecture published by Carrier Bag in October 2025 in which Dryhurst argues that the most consequential aesthetic decisions now happen at the level of protocols, and that artists should design protocols instead of commenting on platforms.", "description_zh": "Carrier Bag 于 2025 年 10 月发布的讲座。Dryhurst 认为，如今最重要的审美决定发生在协议层面，艺术家应当设计协议，而不是评论平台。", "idea_en": "Build the protocol as 'executable critique': a rule set others can use that carries your values downstream.", "idea_zh": "把协议当作“可执行的批判”来建造：一套别人可以使用、并把你的价值观带到下游的规则。", "protocol": "Dryhurst uses his and Holly Herndon's projects as examples: Holly+, which lets anyone use Herndon's voice model under shared rules, the opt-out tool haveibeentrained.com, and Public Diffusion, a model trained only on public-domain data.", "protocol_zh": "Dryhurst 以他和 Holly Herndon 的项目为例：让任何人都能在共同规则下使用 Herndon 声音模型的 Holly+、退出工具 haveibeentrained.com，以及只用公有领域数据训练的模型 Public Diffusion。", "collective": "The talk extends the protocol-art discussion from smart contracts to AI: the work is judged by what other people make and decide under the rules it sets.", "collective_zh": "这场讲座把协议艺术的讨论从智能合约扩展到 AI：作品的价值取决于其他人在它设定的规则下做出和决定了什么。", "keywords": ["protocol art", "Holly+", "Spawning", "AI", "executable critique"], "video": {"url": "https://carrier-bag.net/wp-content/uploads/2025/09/mat_protocol_art_720p.mp4", "platform": "mp4", "id": "https://carrier-bag.net/wp-content/uploads/2025/09/mat_protocol_art_720p.mp4", "thumbnail": "", "embeddable": true}, "paper": {"url": "https://carrier-bag.net/video/protocol-art/", "venue": "Carrier Bag, 2025 (lecture)", "title": "Protocol Art"}, "source_url": "https://carrier-bag.net/video/protocol-art/", "images": [], "also": []}, {"id": "botao-amber-hu--protocol-futuring", "creator_ids": ["botao-amber-hu"], "title": "Protocol Futuring: Speculating Second-Order Dynamics of Protocols in Sociotechnical Infrastructural Futures", "year": 2025, "field": "theory", "sub": "crypto-theory", "mechanisms": ["constraint", "time", "co-authorship"], "substrate": "text", "kind": "publication", "description": "CHI 2026 paper by Botao Amber Hu, Samuel Chua and Helena Rong that proposes 'protocol futuring', a design method that uses protocols as the material of speculative design, tested in a relay workshop on millennial-scale knowledge preservation.", "description_zh": "Botao Amber Hu、Samuel Chua 与 Helena Rong 发表于 CHI 2026 的论文，提出“协议未来化”：一种把协议作为思辨设计材料的设计方法，并通过一场关于千年尺度知识保存的接力工作坊加以检验。", "idea_en": "Speculate on protocols, not products: watch how rules drift when they pass between groups and generations.", "idea_zh": "去推演协议而不是产品：观察规则在群体与世代之间传递时如何漂移。", "protocol": "In the Knowledge Futurama workshop, teams inherited partially formed protocol designs from earlier teams and had to reinterpret and extend them, a relay rule that made drift, jamming and adversarial readings visible.", "protocol_zh": "在 Knowledge Futurama 工作坊中，各团队从前一组那里继承尚未完成的协议设计，必须重新诠释并延续它；这种接力规则让规则的漂移、卡滞与对抗性解读变得可见。", "collective": "The multi-team relay produced protocols that changed through ambiguous handovers, shifting norms and simulated crises; the paper offers the method to HCI and design researchers studying long-lived infrastructures.", "collective_zh": "多团队接力产出的协议在含糊的交接、变化的规范和模拟危机中不断改变；论文把这一方法提供给研究长寿命基础设施的人机交互与设计研究者。", "keywords": ["protocol futuring", "speculative design", "CHI 2026", "infrastructure", "Knowledge Futurama"], "paper": {"url": "https://arxiv.org/abs/2512.06108", "doi": "10.1145/3772318.3790527", "arxiv": "2512.06108", "venue": "CHI 2026", "title": "Protocol Futuring: Speculating Second-Order Dynamics of Protocols in Sociotechnical Infrastructural Futures"}, "source_url": "https://doi.org/10.1145/3772318.3790527", "video": {}, "images": [], "also": []}, {"id": "botao-amber-hu--protocol-as-poetry", "creator_ids": ["botao-amber-hu"], "title": "Protocol as Poetry: A Case Study of Pak's Smart Contract-Based Protocol Art", "year": 2025, "field": "theory", "sub": "crypto-theory", "also": ["onchain"], "mechanisms": ["contract", "participation", "co-authorship"], "substrate": "text", "kind": "publication", "description": "Peer-reviewed paper (ARTECH 2025) that analyses Pak's smart-contract works, from The Fungible and Merge (2021) to Censored (2022) and Not Found (2023), and proposes seven characteristics of protocol art.", "description_zh": "同行评审论文（ARTECH 2025），分析 Pak 的智能合约作品，从 The Fungible 和 Merge（2021）到 Censored（2022）和 Not Found（2023），并提出协议艺术的七个特征。", "idea_en": "In protocol art the smart contract is the medium and collective participation is the message.", "idea_zh": "在协议艺术中，智能合约是媒介，集体参与是讯息。", "protocol": "The paper names seven traits: system-centric composition, autonomous governance, distributed agency and communal authorship, temporal dynamism, economy-driven engagement, poetic messages embedded in interaction rituals, and composability.", "protocol_zh": "论文归纳出七个特征：以系统而非物件为中心的构成、自治治理、分布式能动性与共同作者身份、时间上的动态性、由经济驱动的参与、嵌入互动仪式的诗意讯息，以及可组合性。", "collective": "It is one of the first academic studies to use the term 'protocol art' (or 'protocolism') for smart-contract works and distinguishes it from conceptual, generative, participatory and performance art.", "collective_zh": "这是最早用“协议艺术”（或“协议主义”）来指称智能合约作品的学术研究之一，并将其与观念艺术、生成艺术、参与式艺术和表演艺术区分开来。", "keywords": ["protocol art", "Pak", "Merge", "smart contracts", "annotated portfolio"], "paper": {"url": "https://arxiv.org/abs/2505.12393", "doi": "10.1145/3773699.3773918", "arxiv": "2505.12393", "venue": "ARTECH 2025, 12th International Conference on Digital and Interactive Arts", "title": "Protocol as Poetry: A Case Study of Pak's Smart Contract-Based Protocol Art"}, "source_url": "https://doi.org/10.1145/3773699.3773918", "video": {}, "images": []}, {"id": "jack-butcher--self-checkout", "creator_ids": ["jack-butcher"], "title": "Self Checkout", "year": 2025, "field": "social", "sub": "economies", "also": ["onchain"], "mechanisms": ["exchange", "participation", "currency"], "substrate": "body", "kind": "artwork", "description": "A retail checkout installed at Art Basel Miami Beach (Zero 10, December 2025): visitors pay what they choose and receive a thermal receipt, which is the artwork, while a split-flap display shows the artist's running balance.", "description_zh": "装在迈阿密巴塞尔艺博会（Zero 10，2025 年 12 月）里的一套自助收银台：观众自定金额付款，拿到一张热敏收据——收据就是作品；翻牌显示屏实时显示艺术家的收支余额。", "idea_en": "Take the jibe that an NFT is 'just a receipt' literally, and make every payment lengthen the work and move a public balance.", "idea_zh": "把“NFT 不过是一张收据”这句讽刺当真：每一笔付款都让作品变长，并推动一个公开的余额。", "protocol": "Three in-person kiosks and one kiosk for remote orders accept any amount; each dollar adds length to the printed receipt. Each receipt carries a printed seed phrase giving access to a non-transferable digital companion on Ethereum. Online and in-person payments feed the same displayed balance, which started from the artist's own exhibition costs.", "protocol_zh": "三台现场终端和一台远程订单终端接受任意金额；每一美元都会让打印出的收据更长。每张收据印有一组助记词，可访问以太坊上一个不可转让的数字伴生物。线上与现场付款汇入同一个公开余额，而余额的起点是艺术家自己承担的参展成本。", "collective": "Fair visitors and remote buyers paid varying amounts, lined up for signatures and pushed the displayed balance; press reports gave interim figures only, so no final total is recorded here.", "collective_zh": "艺博会观众和远程买家付出不同金额、排队求签名，并推动显示屏上的余额变化；媒体只报道了中途数字，因此这里不记录最终总额。", "keywords": ["receipt", "pay what you want", "Art Basel Miami Beach", "Zero 10", "Visualize Value", "split-flap"], "images": ["https://jack.art/self-checkout-receipts.png", "https://jack.art/self-checkout.jpg"], "source_url": "https://jack.art/self-checkout", "video": {}, "paper": {}}, {"id": "jack-butcher--1-of-1-of", "creator_ids": ["jack-butcher"], "title": "1 of 1 of ?", "year": 2024, "field": "onchain", "sub": "supply", "mechanisms": ["scarcity", "contract"], "substrate": "bitcoin", "kind": "artwork", "description": "One image issued twice in May 2024: as a unique inscription auctioned at Sotheby's and as a 24-hour open edition. The artist promised to sign a physical work once for every open edition sold.", "description_zh": "同一张图像在 2024 年 5 月以两种方式发行：一件在苏富比拍卖的唯一铭文，以及一个 24 小时开放版数。艺术家承诺每卖出一个开放版数，就在一件实体作品上签一次名。", "idea_en": "The crowd sets the edition size, and the edition size sets how much physical labour the artist owes.", "idea_zh": "人群决定版数，版数决定艺术家欠下多少体力劳动。", "protocol": "For 24 hours anyone could collect the open edition; the unique version was auctioned separately the next day. Butcher's release statement committed him to one hand-drawn signature per open edition on an ink-on-Tyvek work (Proof of Work).", "protocol_zh": "24 小时内任何人都可以收藏开放版数；唯一版次日另行拍卖。Butcher 在发布声明中承诺：每个开放版数，他都要在一件 Tyvek 纸上的墨水作品（Proof of Work）上手签一次。", "collective": "Collectors bought 35,262 editions; on 28 May 2024 Butcher reported that all 35,262 signatures were done (artist's report, not an audited ledger).", "collective_zh": "藏家共买下 35,262 个版数；2024 年 5 月 28 日 Butcher 报告 35,262 个签名全部完成（艺术家自述，并非审计记录）。", "keywords": ["open edition", "Sotheby's", "Ordinals", "signatures", "Proof of Work", "Tyvek"], "images": ["https://images.squarespace-cdn.com/content/v1/6547fdfa39dde777e76d89b5/1717469192803-L427F6J7HGHFUAQBRQC4/bills.png", "https://images.squarespace-cdn.com/content/v1/6547fdfa39dde777e76d89b5/1715790920325-JE3L05XLTD2M7CUGYHJU/1-1-jb.jpg"], "source_url": "https://jack.art/supply", "video": {}, "paper": {}, "also": []}, {"id": "malte-rauch--computation-expanded-field", "creator_ids": ["malte-rauch"], "title": "Computation in the Expanded Field", "year": 2024, "field": "theory", "sub": "crypto-theory", "also": ["onchain"], "mechanisms": ["contract", "constraint", "time"], "substrate": "text", "kind": "publication", "description": "Essay written for World Computer Sculpture Garden, a 'contract show' curated by 0xfff that opened on Ethereum in November 2024, defining protocol art as art that works with the rules that precede and define a computing environment.", "description_zh": "为 0xfff 策划、2024 年 11 月在以太坊上开幕的“合约展”World Computer Sculpture Garden 撰写的文章，把协议艺术定义为处理那些先于并界定计算环境之规则的艺术。", "idea_en": "The blockchain is not a channel for images but the material itself: a set of constraints adopted for art.", "idea_zh": "区块链不是图像的发行渠道，而是材料本身：一组为艺术所采用的约束。", "protocol": "Rauch argues that protocol artists treat distributed computation and its permanence as their medium, writing contracts that act as autonomous works rather than minting images for a marketplace.", "protocol_zh": "Rauch 认为，协议艺术家把分布式计算及其永久性当作媒介，编写作为自治作品运行的合约，而不是为市场铸造图像。", "collective": "The essay accompanies an exhibition that exists as a smart contract with no closing date, with works by artists including Rhea Myers and Sarah Friend, and is cited in academic work on protocol art.", "collective_zh": "这篇文章伴随一个以智能合约形式存在、没有闭幕日期的展览，参展艺术家包括 Rhea Myers 和 Sarah Friend；该文也被协议艺术的学术研究引用。", "keywords": ["protocol art", "World Computer Sculpture Garden", "0xfff", "contract show", "Ethereum"], "paper": {"url": "https://worldcomputersculpture.garden/essay", "venue": "World Computer Sculpture Garden, 2024", "title": "Computation in the Expanded Field"}, "source_url": "https://worldcomputersculpture.garden/", "video": {}, "images": []}, {"id": "jack-butcher--checks", "creator_ids": ["jack-butcher"], "title": "Checks", "year": 2023, "field": "onchain", "sub": "supply", "mechanisms": ["burn", "merge", "scarcity"], "substrate": "ethereum", "kind": "series", "description": "An $8 open edition of 80 checkmarks (January 2023), after Twitter began selling verification. From February 2023 collectors could destroy an edition to get an on-chain Original, then burn Originals into composites with fewer and fewer checks.", "description_zh": "一件 8 美元、画着 80 个对勾的开放版数作品（2023 年 1 月），缘起于推特开始出售认证标志。自 2023 年 2 月起，藏家可以销毁版数换取链上 Original，再把 Originals 烧成对勾越来越少的合成作品。", "idea_en": "Collectors decide which images survive: every composite destroys a work, and choosing not to act is also part of the piece.", "idea_zh": "由藏家决定哪些图像存活：每一次合成都销毁一件作品，而选择不动也是作品的一部分。", "protocol": "Checks – VV Edition was open for 24 hours at $8. Any holder may, with no deadline, burn an Edition to mint an Original with the same token number, rendered as an animated SVG from on-chain data. Two Originals with the same check count can be composited into one: 80 → 40 → 20 → 10 → 5 → 4 → 1 check; the holder picks which token number survives and the parents set the colours. At the last stage 64 single checks make a Black Check, the sum of 4,096 original editions, so at most three can ever exist.", "protocol_zh": "Checks – VV Edition 以 8 美元开放 24 小时。持有者可随时（不设期限）销毁一个 Edition，铸造同编号的 Original，其图像是由链上数据生成的动态 SVG。两个对勾数相同的 Originals 可以合成为一个：80 → 40 → 20 → 10 → 5 → 4 → 1；持有者选择保留哪个编号，颜色由两个“父本”决定。最后一步，64 个单对勾合成一个 Black Check，相当于 4,096 个原始版数，因此最多只能存在三个。", "collective": "16,031 editions were minted in the first 24 hours. By September 2026 about 3,560 Editions had never been migrated and the Originals contract held 5,347 surviving works, so collectors have burned thousands of tokens through migration and compositing (Blockscout).", "collective_zh": "最初 24 小时内共铸造 16,031 个版数。截至 2026 年 9 月，约 3,560 个 Edition 从未迁移，Originals 合约中存活 5,347 件作品——藏家通过迁移与合成已销毁数千枚代币（据 Blockscout）。", "keywords": ["Checks", "VV Edition", "Originals", "compositing", "Black Check", "Jalil Wahdatehagh", "Twitter verification"], "images": ["https://framerusercontent.com/images/Er5ZzBJPeH0FP4XccvWbrg3LU.jpg", "https://framerusercontent.com/images/zn2CN7FtJNuI5Y8lIYniJGsEwI.gif?scale-down-to=1024"], "source_url": "https://jack.art/checks-originals", "contract_url": "https://etherscan.io/address/0x036721e5A769Cc48B3189EFbb9ccE4471E8A48B1", "video": {}, "paper": {}, "also": []}, {"id": "jack-butcher--opepen-edition", "creator_ids": ["jack-butcher"], "title": "Opepen Edition", "year": 2023, "field": "onchain", "sub": "co-authored", "mechanisms": ["governance", "co-authorship", "chance"], "substrate": "ethereum", "kind": "platform", "description": "16,000 identical tokens (a geometric Pepe) that became a release system: artists propose sets of images, and holders opt their unrevealed tokens into the sets they want to become.", "description_zh": "16,000 枚相同的代币（一个几何化的 Pepe），后来变成一套发布系统：艺术家提交图像套组，持有者把尚未揭示的代币报名进自己想成为的那一套。", "idea_en": "Holders do not vote on proposals; they commit their own token to the image it will become.", "idea_zh": "持有者不是对提案投票，而是把自己的代币押在它将变成的那张图像上。", "protocol": "Opepen was a 60-minute open edition (8 January 2023). Tokens are revealed in sets of 80 with edition groups of 1, 4, 5, 10, 20 and 40. Holders of unrevealed tokens sign messages to opt into a proposed set; a set is released once opt-in demand reaches twice its supply, and tokens are then chosen at random, so opting in does not guarantee an allocation. Since March 2024 each token may opt into one set at a time; anyone may submit a set.", "protocol_zh": "Opepen 是 60 分钟的开放版数（2023 年 1 月 8 日）。代币以每套 80 枚的方式揭示，分为 1、4、5、10、20、40 六个版数组。未揭示代币的持有者通过签名报名某个提案套组；报名量达到供应量的两倍时该套发布，再随机抽取代币，所以报名不保证分配到。自 2024 年 3 月起，每枚代币同一时间只能报名一套；任何人都可以提交套组。", "collective": "Set 001 (8x8, by Butcher) was submitted on 30 April 2023 and reached consensus on 3 May 2023; later sets came from many artists. In September 2026 the contract counted 15,766 tokens held by about 8,500 addresses (Blockscout).", "collective_zh": "Set 001（8x8，Butcher 本人作品）于 2023 年 4 月 30 日提交，5 月 3 日达成共识；此后的套组来自众多艺术家。2026 年 9 月，合约记录 15,766 枚代币，分布在约 8,500 个地址中（据 Blockscout）。", "keywords": ["Opepen", "opt-in", "consensus", "sets", "Pepe", "batz", "Jalil Wahdatehagh"], "images": ["https://opepen.art/og/intro.png", "https://api.opepen.art/v1/render/sets/9dde6d38-2e6b-4e29-8f80-37a4450d49df/og?", "https://images.squarespace-cdn.com/content/v1/6547fdfa39dde777e76d89b5/eed1a6b3-b3a6-45df-89bc-8c9afce766d5/explainer.jpg"], "source_url": "https://jack.art/opepen-edition", "contract_url": "https://etherscan.io/address/0x6339e5E072086621540D0362C4e3Cea0d643E114", "video": {}, "paper": {}, "also": []}, {"id": "rhea-myers--proof-of-work", "creator_ids": ["rhea-myers"], "title": "Proof of Work: Blockchain Provocations 2011–2021", "year": 2023, "field": "theory", "sub": "crypto-theory", "also": ["onchain"], "mechanisms": ["contract", "currency", "autonomy"], "substrate": "text", "kind": "publication", "description": "Book (Urbanomic / Art Editions, 2023) collecting Myers's blockchain artworks from 2011 to 2021 with annotations, alongside her essays, reviews and fiction on crypto culture and art.", "description_zh": "一本书（Urbanomic / Art Editions，2023），收录 Myers 2011 至 2021 年的区块链作品及注释，以及她关于加密文化与艺术的文章、评论和小说。", "idea_en": "Use the tropes of Conceptual art to ask what a blockchain reveals about value and ownership.", "idea_zh": "借用观念艺术的套路，追问区块链揭示了关于价值与所有权的什么。", "protocol": "Many works in the book are small smart contracts or token schemes with a conceptual twist, whose rules collectors and the network carry out; the texts explain each rule and its art-historical reference.", "protocol_zh": "书中许多作品是带有观念转折的小型智能合约或代币机制，其规则由藏家和网络执行；文字部分解释每条规则及其艺术史参照。", "collective": "The book documents a decade of work that anticipated the NFT boom, and was also issued as an NFT special edition by Urbanomic.", "collective_zh": "这本书记录了先于 NFT 热潮的十年创作，Urbanomic 还发行了它的 NFT 特别版。", "keywords": ["Urbanomic", "crypto art", "smart contracts", "Conceptual art", "net.art"], "images": ["https://www.urbanomic.com/wp-content/uploads/2021/10/Front-Cover.jpg"], "paper": {"url": "https://www.urbanomic.com/book/proof-of-work/", "venue": "Urbanomic / Art Editions, 2023", "title": "Proof of Work: Blockchain Provocations 2011–2021"}, "source_url": "https://www.urbanomic.com/book/proof-of-work/", "video": {}}, {"id": "summer-of-protocols--program", "creator_ids": ["summer-of-protocols", "venkatesh-rao"], "title": "Summer of Protocols", "year": 2023, "field": "theory", "sub": "crypto-theory", "mechanisms": ["constraint", "governance", "participation"], "substrate": "text", "kind": "platform", "description": "Research programme commissioned by the Ethereum Foundation that ran seasons in 2023, 2024 and 2025, funding researchers, artists and engineers to study protocols across fields from blockchains to traffic, safety and diplomacy.", "description_zh": "由以太坊基金会委托的研究计划，在 2023、2024、2025 年各举办一季，资助研究者、艺术家和工程师跨领域研究协议，从区块链到交通、安全与外交。", "idea_en": "Treat protocols as a general design material that can be studied, taught and made by artists as well as engineers.", "idea_zh": "把协议当作一种通用的设计材料：它可以被研究、被教授，也可以由艺术家和工程师共同创作。", "protocol": "Each season invited cohorts of researchers to produce essays, artworks and tools under a shared brief; outputs are published openly and discussed in a public forum and newsletter.", "protocol_zh": "每一季邀请一批研究者在共同主题下产出文章、作品和工具；成果公开发布，并在公共论坛和通讯中讨论。", "collective": "SoP23 brought together 12 core and 18 affiliate researchers; across its seasons the programme counts 70-odd alumni and more than 100 research outputs, including the Protocol Reader, the ProtocolKit and a 358-page proto-textbook, and it continues as the Protocol Institute.", "collective_zh": "SoP23 汇集了 12 位核心研究者和 18 位附属研究者；各季累计约 70 位参与者、100 多项研究成果，包括 Protocol Reader、ProtocolKit 和一本 358 页的原型教科书；该计划之后延续为 Protocol Institute。", "keywords": ["Ethereum Foundation", "protocol studies", "Protocol Reader", "Protocol Institute", "Protocolized"], "images": ["https://summerofprotocols.com/wp-content/uploads/2024/03/SoP24-Hero-scaled.webp"], "paper": {"url": "https://summerofprotocols.com/about", "venue": "Summer of Protocols / Ethereum Foundation", "title": "About Summer of Protocols"}, "source_url": "https://summerofprotocols.com/", "video": {}, "also": []}, {"id": "venkatesh-rao--unreasonable-sufficiency", "creator_ids": ["venkatesh-rao", "summer-of-protocols"], "title": "The Unreasonable Sufficiency of Protocols", "year": 2023, "field": "theory", "sub": "crypto-theory", "mechanisms": ["constraint", "governance"], "substrate": "text", "kind": "publication", "description": "Pilot study by Venkatesh Rao, Tim Beiko, Danny Ryan, Josh Stark, Trent Van Epps and Bastian Aue, released in March 2023 to open the Summer of Protocols, that asks why simple protocols coordinate so much complex behaviour.", "description_zh": "由 Venkatesh Rao、Tim Beiko、Danny Ryan、Josh Stark、Trent Van Epps 与 Bastian Aue 撰写的试点研究，2023 年 3 月发布，作为 Summer of Protocols 的开篇，追问为什么简单的协议能协调如此复杂的行为。", "idea_en": "A small set of codified rules can be unreasonably sufficient: it lets large, complex cooperation emerge.", "idea_zh": "一小组成文规则可以“不合理地充分”：它能让大规模的复杂合作涌现出来。", "protocol": "The paper defines a protocol as 'a stratum of codified behavior that allows for the construction or emergence of complex coordinated behaviors at adjacent loci', and describes protocols along dimensions such as generativity, legibility, evolvability, legitimacy, play value and mortality.", "protocol_zh": "论文把协议定义为“一层成文的行为规范，使相邻位置上复杂的协调行为得以构建或涌现”，并从生成性、可读性、可演化性、正当性、游戏价值和寿命等维度描述协议。", "collective": "The text framed the research questions for the first Summer of Protocols cohort and was revised and republished in 2024 as a reference work for the programme.", "collective_zh": "这篇文本为第一届 Summer of Protocols 的研究者设定了研究问题，并于 2024 年修订再版，成为该计划的参考文献。", "keywords": ["Summer of Protocols", "coordination", "Ethereum", "ossification", "protocol theory"], "images": ["https://summerofprotocols.com/wp-content/uploads/2024/03/joshd4078_intricate_flowchart_where_symbols_morph_and_transform_1cccf476-f315-4f8f-881a-dd323482c3b4-jpg.webp"], "paper": {"url": "https://summerofprotocols.com/wp-content/uploads/2024/03/The-Unreasonable-Sufficiency-of-Protocols.pdf", "venue": "Summer of Protocols, 2023 (revised 2024)", "title": "The Unreasonable Sufficiency of Protocols"}, "source_url": "https://summerofprotocols.com/the-unreasonable-sufficiency-of-protocols-web", "video": {}, "also": []}, {"id": "pak--censored", "creator_ids": ["pak"], "title": "Censored", "year": 2022, "field": "onchain", "sub": "co-authored", "mechanisms": ["co-authorship", "participation", "time"], "substrate": "ethereum", "kind": "series", "description": "An open edition made with Julian Assange (February 2022): for 48 hours anyone could mint a token carrying a message of their own, shown under a black censor bar until Assange was freed.", "description_zh": "与朱利安·阿桑奇合作的开放版数（2022 年 2 月）：48 小时内任何人都可以铸造一枚写有自己留言的代币，留言被黑色审查条遮住，直到阿桑奇获释。", "idea_en": "Every buyer writes part of the work, and a real-world event (a prisoner's release) is the key that reveals it.", "idea_zh": "每位买家写下作品的一部分，而一个现实事件（囚徒获释）是揭开它的钥匙。", "protocol": "During the 48-hour window buyers paid any amount they chose and tokenized a message; there was no limit on the number of messages. Each token stores its text and its initial price on-chain and renders the message covered by a censor bar, with a 'Censored' trait that was to switch off only on Assange's release.", "protocol_zh": "48 小时窗口内，买家自定金额，把一条留言铸成代币，数量不设上限。每枚代币在链上保存文字和初始价格，渲染时留言被审查条遮住；“Censored”属性只有在阿桑奇获释时才会关闭。", "collective": "Tens of thousands of buyers wrote messages (token ids on the contract run past 29,700; initial prices range from 0.01 ETH upward). In June 2024, after Assange's release, Pak uncensored the tokens; the contract lists about 18,500 holders in September 2026 (Blockscout).", "collective_zh": "数万名买家写下留言（合约上的代币编号超过 29,700，初始价格从 0.01 ETH 起不等）。2024 年 6 月阿桑奇获释后，Pak 解除了代币的审查；2026 年 9 月合约约有 18,500 个持有地址（据 Blockscout）。", "keywords": ["Julian Assange", "WikiLeaks", "pay what you want", "open edition", "messages", "uncensored"], "images": ["https://www.artrights.me/wp-content/uploads/2022/02/Censored-By-Pak-Announcement-Website.jpeg", "https://www.cryptoblogs.io/wp-content/uploads/2024/02/Pak-was-here-Website.jpg"], "source_url": "https://www.artrights.me/en/censored-the-nft-project-by-pak-in-collaboration-with-julian-assange/", "contract_url": "https://etherscan.io/address/0xDa22422592Ee3623c8d3c40Fe0059CdEcF30CA79", "video": {}, "paper": {}, "also": []}, {"id": "pak--clock", "creator_ids": ["pak"], "title": "Clock", "year": 2022, "field": "autonomous", "sub": "dao", "also": ["onchain"], "mechanisms": ["time", "governance"], "substrate": "ethereum", "kind": "artwork", "description": "The single-edition token of Censored: a counter of the days Julian Assange had spent in prison, updated daily. It was auctioned in February 2022 and bought by AssangeDAO, a crowd-funded collective.", "description_zh": "Censored 系列中的单版代币：一个每天更新、记录朱利安·阿桑奇在狱中天数的计数器。2022 年 2 月拍卖，由众筹集体 AssangeDAO 买下。", "idea_en": "A 1/1 whose only content is a running count of a political fact, sold so that a crowd had to organise to own it.", "idea_zh": "一件单版作品，内容只是一个政治事实的持续计数；它的出售方式迫使一群人组织起来才能拥有它。", "protocol": "Token #1 of the Censored contract renders the number of days of Assange's imprisonment and changes every day; it was sold at auction to fund Assange's legal defence. The clock was set to stop on his release.", "protocol_zh": "Censored 合约的 1 号代币显示阿桑奇被关押的天数，每天变化；它通过拍卖出售，为阿桑奇的法律辩护筹款。时钟设定在他获释时停止。", "collective": "AssangeDAO pooled ETH from more than 10,000 contributors through Juicebox (as reported by the DAO and press) and won the auction with 16,593 ETH, about $52.8 million at the time. The token now sits in a multisig safe; the clock stopped when Assange was freed in June 2024.", "collective_zh": "AssangeDAO 通过 Juicebox 从一万多名出资者那里汇集 ETH（据该 DAO 与媒体报道），以 16,593 ETH（当时约 5,280 万美元）赢得拍卖。这枚代币现存于一个多签钱包中；2024 年 6 月阿桑奇获释时，时钟停止。", "keywords": ["AssangeDAO", "Juicebox", "Julian Assange", "dynamic NFT", "crowdfund", "Wau Holland Foundation"], "images": ["https://www.cryptoblogs.io/wp-content/uploads/2024/02/One-Thousands-Thirty-Two-Clock-1.jpg"], "source_url": "https://fortune.com/2022/02/09/supporters-of-wikileaks-founder-julian-assange-raise-56-million-to-buy-an-nft-for-his-u-s-extradition-battle/", "contract_url": "https://etherscan.io/nft/0xDa22422592Ee3623c8d3c40Fe0059CdEcF30CA79/1", "video": {}, "paper": {}}, {"id": "jacob-horne--hyperstructures", "creator_ids": ["jacob-horne"], "title": "Hyperstructures", "year": 2022, "field": "theory", "sub": "crypto-theory", "mechanisms": ["autonomy", "exchange", "time"], "substrate": "text", "kind": "publication", "description": "Essay published on 16 January 2022 that defines hyperstructures as 'crypto protocols that can run for free and forever, without maintenance, interruption or intermediaries'.", "description_zh": "2022 年 1 月 16 日发表的文章，把“超结构”定义为“能够免费、永久运行，无需维护、不会中断、没有中介的加密协议”。", "idea_en": "Build the protocol so it keeps running after you leave; then others can build on it.", "idea_zh": "把协议做成你离开后仍能运行的样子，别人才能在上面继续建造。", "protocol": "Horne lists the properties of a hyperstructure: unstoppable, free, valuable, expansive, permissionless, positive-sum and credibly neutral, running entirely onchain for as long as its chain exists.", "protocol_zh": "Horne 列出超结构的特性：不可阻止、免费、有价值、可扩展、无需许可、正和、可信中立，完全在链上运行，只要所在的链存在就一直运行。", "collective": "The term spread quickly among onchain builders and artists and shaped Zora's own protocol design; it is often used to describe artworks and platforms meant to outlive their authors.", "collective_zh": "这个词在链上开发者和艺术家中迅速传播，也塑造了 Zora 自身的协议设计；它常被用来描述那些意在比作者存续更久的作品与平台。", "keywords": ["hyperstructures", "Zora", "permissionless", "credible neutrality", "onchain"], "images": ["https://jacob.energy/img/hyper.png"], "paper": {"url": "https://jacob.energy/hyperstructures.html", "venue": "jacob.energy, 2022", "title": "Hyperstructures"}, "source_url": "https://jacob.energy/hyperstructures.html", "video": {}, "also": []}, {"id": "pak--matter", "creator_ids": ["pak"], "title": "Matter* (mass.black)", "year": 2022, "field": "onchain", "sub": "supply", "mechanisms": ["merge", "constraint", "chance"], "substrate": "ethereum", "kind": "game", "description": "A month-long 'treasure hunt' for Merge holders (1–30 April 2022): new Matter* tokens were awarded to Merge tokens that met published criteria about merges and mass at the end snapshot.", "description_zh": "为 Merge 持有者设计的一个月“寻宝”（2022 年 4 月 1 日至 30 日）：按照公布的合并次数与质量标准，在结束快照时符合条件的 Merge 代币获得新的 Matter* 代币。", "idea_en": "Reward specific collective behaviours (merging often, hoarding mass, cannibalising) so holders play the contract as a game.", "idea_zh": "奖励特定的集体行为（频繁合并、囤积质量、互相吞并），让持有者把合约当作游戏来玩。", "protocol": "Tiers of Matter* went to Merge tokens by rule: 'Hunters and Traps' for tokens with 4+ merges, 'Thief's Wise Hands' for mass × merges ≥ 100 (stealing supply from 'Scavenger's Weak Hands', mass ≥ 10), 'Cannibalism' for the most merges, 'Kings of the Hill' for the most mass, 'Titan' for the alpha, 'Three Lucky Giants' at random, and a hidden challenge tier that would unlock only if Merge supply fell below 20,000. Distribution used the end snapshot; one token could win several.", "protocol_zh": "Matter* 各层级按规则发给 Merge 代币：合并 4 次以上得“Hunters and Traps”；质量 × 合并次数 ≥ 100 得“Thief's Wise Hands”（从质量 ≥ 10 的“Scavenger's Weak Hands”中抢走名额）；合并最多得“Cannibalism”；质量最大得“Kings of the Hill”；alpha 得“Titan”；另有随机抽取的“Three Lucky Giants”，以及只有在 Merge 总量跌破 20,000 时才会解锁的隐藏挑战层。按结束快照分发，一枚代币可以赢得多个。", "collective": "The site reports a Matter* supply of 1,481 with 1,395 generated. The 'Thief' tier took all 450 places, so 'Scavenger's Weak Hands' generated none, and the challenge tier stayed locked because Merge supply did not fall below 20,000 during the event.", "collective_zh": "网站显示 Matter* 总量为 1,481，实际生成 1,395 枚。“Thief”层级拿走了全部 450 个名额，因此“Scavenger's Weak Hands”一枚也没有生成；活动期间 Merge 总量没有跌破 20,000，挑战层始终未解锁。", "keywords": ["Merge", "Matter", "Antimatter", "snapshot", "treasure hunt", "mass.black"], "images": ["https://mass.black/mass.black.png"], "source_url": "https://mass.black/", "video": {}, "paper": {}, "also": []}, {"id": "ruth-catlow--radical-friends", "creator_ids": ["ruth-catlow", "penny-rafferty"], "title": "Radical Friends: Decentralised Autonomous Organisations and the Arts", "year": 2022, "field": "theory", "sub": "crypto-theory", "also": ["autonomous"], "mechanisms": ["governance", "contract", "autonomy"], "substrate": "text", "kind": "publication", "description": "Book edited by Ruth Catlow and Penny Rafferty (Torque Editions, 2022) with essays, interviews, exercises and prototypes on DAOs as tools for artists to encode rules, relations and values into shared ventures.", "description_zh": "Ruth Catlow 与 Penny Rafferty 主编的书（Torque Editions，2022），以文章、访谈、练习和原型讨论 DAO 如何让艺术家把规则、关系与价值写进共同事业。", "idea_en": "The most radical blockchain tool for art may be the organisation, not the token.", "idea_zh": "对艺术来说，最激进的区块链工具也许是组织，而不是代币。", "protocol": "The book treats a DAO as a rule set that peers write together and run on a blockchain: who can join, how decisions are made, how money flows. It includes exercises for groups to draft their own.", "protocol_zh": "书中把 DAO 看作同伴们共同编写、运行在区块链上的一组规则：谁可以加入、如何决策、资金如何流动；并附有供团体起草自己规则的练习。", "collective": "It collects more than five years of research by the editors and contributors such as Primavera De Filippi, Ramon Amaro, Mitchell F. Chan and eeefff, and refocused attention from NFTs toward collective organisation in the arts.", "collective_zh": "它汇集了编者及 Primavera De Filippi、Ramon Amaro、Mitchell F. Chan、eeefff 等撰稿人五年多的研究，把关注点从 NFT 转向艺术中的集体组织。", "keywords": ["DAO", "Furtherfield", "Torque Editions", "governance", "art organisations"], "images": ["https://torquetorque.net/wp-content/uploads/1-Radical-Freinds-Full-Cover-1200x833.png"], "paper": {"url": "https://torquetorque.net/publications/radical-friends/", "venue": "Torque Editions, 2022", "title": "Radical Friends: Decentralised Autonomous Organisations and the Arts"}, "source_url": "https://ruthcatlow.net/?works=radical-friends-decentralised-autonomous-organisations-and-the-arts", "video": {}}, {"id": "kei-kreutler--prehistory-of-daos", "creator_ids": ["kei-kreutler"], "title": "A Prehistory of DAOs", "year": 2021, "field": "theory", "sub": "crypto-theory", "mechanisms": ["governance", "currency"], "substrate": "text", "kind": "publication", "description": "Essay published by Gnosis Guild in July 2021, subtitled 'Cooperatives, gaming guilds, and the networks to come', that traces DAOs back to the cooperative movement and online game guilds.", "description_zh": "Gnosis Guild 于 2021 年 7 月发表的文章，副标题为“合作社、游戏公会与即将到来的网络”，把 DAO 的源头追溯到合作社运动和网络游戏公会。", "idea_en": "DAOs are not new: they are cooperatives and guilds with their rules written in code.", "idea_zh": "DAO 并不新：它们是把规则写进代码的合作社和公会。", "protocol": "Kreutler reads DAOs as organisations where a software protocol sets the operating rules, 'placing automation at its center and humans at its edges', and compares them to the Rochdale cooperative principles of 1844 and guilds' loot-sharing systems such as Dragon Kill Points.", "protocol_zh": "Kreutler 把 DAO 理解为由软件协议设定运行规则的组织，“把自动化置于中心、把人置于边缘”，并将其与 1844 年罗奇代尔合作社原则以及“屠龙点数”（DKP）等公会战利品分配制度相比较。", "collective": "The essay and its LisCon talk were widely shared in the 2021 DAO wave and are often cited by art DAOs and researchers looking for a history longer than Ethereum.", "collective_zh": "这篇文章及其在 LisCon 的演讲在 2021 年 DAO 热潮中被广泛传播，常被寻找比以太坊更长历史的艺术 DAO 和研究者引用。", "keywords": ["DAO", "cooperatives", "guilds", "DKP", "Gnosis Guild"], "images": ["https://storage.googleapis.com/papyrus_images/1ec3d26160223fb58c11a916986a6b38312b19eb14dfd8c90454cb312b3a2bea.png"], "video": {"url": "https://vimeo.com/637505710", "platform": "vimeo", "id": "637505710", "thumbnail": "https://i.vimeocdn.com/video/1280725269-66d2701f8b62642a9c11d37b5e8e298b50849752bb4f1e790?f=webp&region=us", "embeddable": true}, "paper": {"url": "https://gnosisguild.mirror.xyz/t4F5rItMw4-mlpLZf5JQhElbDfQ2JRVKAzEpanyxW1Q", "venue": "Gnosis Guild, 2021", "title": "A Prehistory of DAOs: Cooperatives, gaming guilds, and the networks to come"}, "source_url": "https://gnosisguild.mirror.xyz/t4F5rItMw4-mlpLZf5JQhElbDfQ2JRVKAzEpanyxW1Q", "also": []}, {"id": "pak--lost-poets", "creator_ids": ["pak"], "title": "Lost Poets", "year": 2021, "field": "onchain", "sub": "co-authored", "mechanisms": ["burn", "co-authorship", "chance"], "substrate": "ethereum", "kind": "game", "description": "A collectible strategy game in acts: 65,536 Pages were sold in September 2021, holders burned Pages to claim AI-generated Poets, then burned more Pages to name their Poets and give them words.", "description_zh": "一个分幕进行的收藏策略游戏：2021 年 9 月售出 65,536 张 Pages，持有者销毁 Pages 领取 AI 生成的 Poets，再继续销毁 Pages 为自己的 Poet 命名、赋予词语。", "idea_en": "Give buyers a fuel (Pages) that can only be spent by destroying it, and let them spend it on authoring the characters they own.", "idea_zh": "给买家一种只能靠销毁来使用的燃料（Pages），让他们用它来书写自己拥有的角色。", "protocol": "Act I sold Pages (an ERC-1155 token) at 0.32 ETH, with 7,586 Pages airdropped to holders of at least 25 ASH. For two weeks one Page could be burned to claim one Poet (ERC-721); after that no more conversions were possible. 1,024 Origin Poets with special permissions were distributed at random. Burning further Pages into a Poet grants a name change and a few words that the holder can write into the Poet's metadata.", "protocol_zh": "第一幕以 0.32 ETH 出售 Pages（ERC-1155 代币），另向持有至少 25 ASH 的地址空投 7,586 张。之后两周内，一张 Page 可销毁换取一个 Poet（ERC-721），期限过后不能再转换。1,024 个拥有特殊权限的 Origin Poet 随机分发。再把 Pages 烧进 Poet，可以获得一次改名机会和几个词，持有者可把这些词写进 Poet 的元数据。", "collective": "All 65,536 Pages sold in about two hours of a planned 48-hour sale. Holders then named their Poets and inscribed short lines (on-chain names include 'The Last Poet' and 'Pope Francis'), so the collection's texts were written by its owners. In September 2026 the Poets contract listed about 5,570 holders (Blockscout).", "collective_zh": "原定 48 小时的发售中，65,536 张 Pages 约两小时售罄。持有者随后给 Poets 起名、刻写短句（链上名称包括“The Last Poet”“Pope Francis”），整套作品的文字由藏家写成。2026 年 9 月，Poets 合约约有 5,570 个持有地址（据 Blockscout）。", "keywords": ["Pages", "Poets", "Origins", "ERC-1155", "naming", "AI portraits", "ASH"], "images": ["https://lostpoets.xyz/img/lostpoets_card.png", "https://d1xxei964ioe0z.cloudfront.net/full/19bbbc3fd5354b3c21fe4bf29703ceb82ddb895eb719aae685e21f38d30619e7.png", "https://d1xxei964ioe0z.cloudfront.net/full/0e1490cb36bb726bb2c26ab21e28f8bdf5bf114cba09e022c5a6d34c364f31e5.png"], "source_url": "https://lostpoets.xyz", "contract_url": "https://etherscan.io/address/0x4b3406a41399c7FD2BA65cbC93697Ad9E7eA61e5", "video": {}, "paper": {}, "also": []}, {"id": "pak--merge", "creator_ids": ["pak"], "title": "Merge", "year": 2021, "field": "onchain", "sub": "supply", "mechanisms": ["merge", "scarcity", "circulation"], "substrate": "ethereum", "kind": "artwork", "description": "An open sale of 'mass' on Nifty Gateway (2–4 December 2021). Each buyer's units became one dynamic token, and any two tokens that meet in the same wallet fuse, so the number of tokens only goes down.", "description_zh": "2021 年 12 月 2 日至 4 日在 Nifty Gateway 上公开出售的“质量”（mass）。每位买家的单位合成一枚动态代币；任何两枚代币只要进入同一个钱包就会融合，所以代币总数只减不增。", "idea_en": "A game of extinction: a contract where every transfer can consume a token, so the market itself shrinks the work toward one survivor.", "idea_zh": "一场灭绝游戏：每次转移都可能吞掉一枚代币，市场本身把作品一步步缩向唯一的幸存者。", "protocol": "During the 48-hour sale anyone could buy any number of mass units; at the end each collector's units were merged into one token. The contract lets an ordinary wallet hold only one token: when a second arrives, the larger mass absorbs the smaller and the smaller is burned (whitelisted addresses such as the Nifty Gateway omnibus are exempt). Each token has one of four classes, drawn as a white, yellow, blue-ringed or red-ringed sphere; the single largest mass is the 'alpha', drawn black with a white ring, and every sphere is sized relative to it.", "protocol_zh": "48 小时发售期间，任何人都可以买任意数量的质量单位；结束时，每位藏家的单位合并为一枚代币。合约规定普通钱包只能持有一枚：第二枚到达时，质量大的吞并质量小的，小的被销毁（Nifty Gateway 托管地址等白名单地址除外）。每枚代币属于四个等级之一，分别画成白色、黄色、蓝环或红环的球体；全场质量最大的一枚是“alpha”，画成带白环的黑球，其余球体的大小都相对它来计算。", "collective": "28,983 collectors spent $91,806,519 on 312,686 units of mass, which became one token each (Nifty Gateway / Gemini). Secondary trading and deliberate merging then consumed tokens: by September 2026 the contract's totalSupply was 18,961, held by about 9,635 addresses (Blockscout).", "collective_zh": "28,983 位藏家花费 91,806,519 美元买下 312,686 个质量单位，每人合成一枚代币（据 Nifty Gateway / Gemini）。此后的二级交易和有意合并不断吞掉代币：截至 2026 年 9 月，合约的 totalSupply 为 18,961，分布在约 9,635 个地址中（据 Blockscout）。", "keywords": ["mass", "alpha", "Nifty Gateway", "open edition", "one token per wallet", "extinction"], "video": {"url": "https://x.com/muratpak/status/1465360503400718342", "platform": "x", "id": "1465360503400718342", "thumbnail": "https://pbs.twimg.com/ext_tw_video_thumb/1465360101871697927/pu/img/zDKrvwxobvS_eHFg.jpg", "embeddable": true}, "images": ["https://images.ctfassets.net/jg6lo9a2ukvr/3W6db5n9dQJBEIUBbs4G0m/341b8cef31c4f63ed4ad3ae61d4a0ce2/Pak_Merge.jpeg"], "source_url": "https://www.gemini.com/blog/paks-merge-drop-on-nifty-gateway-breaks-records-in-largest-ever-public-sale", "contract_url": "https://etherscan.io/address/0xc3f8a0F5841aBFf777d3eefA5047e8D413a1C9AB", "paper": {}, "also": []}, {"id": "tom-sachs--rocket-factory", "creator_ids": ["tom-sachs"], "title": "Rocket Factory", "year": 2021, "field": "onchain", "sub": "supply", "mechanisms": ["merge", "burn", "chance"], "substrate": "ethereum", "kind": "series", "description": "3,000 NFT rocket parts (nose cones, bodies, tail assemblies) in 30 brand liveries. Collectors combine three parts into a rocket, and may ask the studio to build and launch a physical twin.", "description_zh": "3,000 个 NFT 火箭零件（箭头、箭身、尾翼），共 30 种品牌涂装。藏家把三个零件组合成一枚火箭，还可以请工作室造出实体孪生火箭并发射。", "idea_en": "The collector base, not the artist, decides which of 113,000+ possible rockets get built, and the studio has to follow.", "idea_zh": "由藏家群体而非艺术家决定 113,000 多种可能中哪些火箭被造出来，工作室只能照做。", "protocol": "One nose cone, one body and one tail assembly can be combined into a Completed Rocket NFT; the three component NFTs are burned ('comburning'). Same-brand parts make a Perfect Rocket, mixed parts a Frankenrocket. A rocket holder can choose the Launch Option, after which the studio builds and launches a physical rocket and returns recovered parts in a display box with launch video; the physical twin can also be donated or destroyed.", "protocol_zh": "一个箭头、一个箭身和一个尾翼可以组合成一枚 Completed Rocket NFT，三个零件 NFT 随之销毁（“comburning”）。同品牌零件组成 Perfect Rocket，混搭则是 Frankenrocket。火箭持有者可以选择发射选项：工作室造出实体火箭并发射，把回收的零件装进展示盒、连同发射视频寄回；实体孪生也可以选择捐赠或销毁。", "collective": "Collectors trade parts to chase scarce Perfect Rockets (for example 87 Chanel and 3 Hello Kitty sets exist). By the 2022 Wallpaper* Design Awards there had been seven public launches, including Governors Island in New York, a Miami ballpark and SoHo; LACMA joined with a collaborative Frankenrocket.", "collective_zh": "藏家交换零件以追逐稀有的 Perfect Rocket（例如 Chanel 套件只有 87 套，Hello Kitty 只有 3 套）。到 2022 年 Wallpaper* 设计奖评选时已公开发射七次，地点包括纽约总督岛、迈阿密一座棒球场和苏荷区；洛杉矶郡立美术馆也参与组装了一枚合作 Frankenrocket。", "keywords": ["comburn", "Perfect Rocket", "Frankenrocket", "launch", "LACMA", "physical twin"], "images": ["https://www.tomsachsrocketfactory.com/tsrf.jpeg", "https://unframed.lacma.org/sites/default/files/attachments/TSRF%20LAUNCH%20%281%29.jpg", "https://unframed.lacma.org/sites/default/files/attachments/TSRF%20ROCKETS%20%281%29.jpg"], "source_url": "https://unframed.lacma.org/2021/11/09/nfts-and-museum-tom-sachs-rocket-launch", "video": {}, "paper": {}, "also": []}, {"id": "damien-hirst--the-currency", "creator_ids": ["damien-hirst"], "title": "The Currency", "year": 2021, "field": "onchain", "sub": "supply", "mechanisms": ["burn", "contract", "exchange"], "substrate": "other-chain", "kind": "series", "description": "10,000 NFTs, each tied to a unique hand-painted dot work on paper, released with HENI in July 2021. Each buyer had a year to keep the NFT or swap it for the painting; whichever was not chosen was destroyed.", "description_zh": "与 HENI 合作于 2021 年 7 月发行的 10,000 个 NFT，每个对应一幅独一无二的纸上手绘点画。每位买家有一年时间决定保留 NFT 还是换成画作；没被选中的那一方会被销毁。", "idea_en": "Make every owner choose between the token and the object, and let the sum of those choices decide how much of the work physically survives.", "idea_zh": "让每位藏家在代币与实物之间二选一，这些选择的总和决定作品有多少以实体形式留存。", "protocol": "Holders of each NFT (on the Palm blockchain) could, until 27 July 2022, exchange it for the matching paper work, which burned the NFT; if they kept the NFT, the paper work would be burned. Hirst kept 1,000 works himself and chose the NFT for them, so their papers burned too.", "protocol_zh": "每个 NFT（在 Palm 区块链上）的持有者在 2022 年 7 月 27 日前可以换取对应的纸本作品，此时 NFT 被销毁；若保留 NFT，纸本作品就会被烧掉。赫斯特自己保留了 1,000 件并选择保留 NFT，所以这些纸本也被烧掉。", "collective": "When the exchange period closed, 5,149 holders had chosen the physical work and 4,851 the NFT (HENI). The 4,851 papers were burned publicly during The Currency exhibition at Newport Street Gallery, London, from September to October 2022, starting on 11 October with Hirst's own 1,000.", "collective_zh": "兑换期结束时，5,149 位持有者选择了实物，4,851 位选择了 NFT（据 HENI）。2022 年 9 月至 10 月，这 4,851 张纸本在伦敦 Newport Street Gallery 的 The Currency 展览中被当众焚烧，10 月 11 日从赫斯特自己保留的 1,000 张开始。", "keywords": ["HENI", "Palm", "physical or NFT", "burn", "Newport Street Gallery", "dot paintings"], "video": {"url": "https://www.youtube.com/watch?v=vEsVJJy1od4", "platform": "youtube", "id": "vEsVJJy1od4", "thumbnail": "https://i.ytimg.com/vi/vEsVJJy1od4/maxresdefault.jpg", "embeddable": true}, "images": ["https://www.designboom.com/wp-content/uploads/2022/10/damien-hirst-nft-the-currency-designboom-fb.jpg", "https://static.frieze.com/files/styles/frieze_teaser/public/article/thumbnail/damien-hirst-the-currency-2.jpg?itok=USxR2EYc", "https://resources.heni.com/6190a77a-761c-4cc5-914b-b9c296c09c00.png?width=1024"], "source_url": "https://heni.com/nft/more-info/the-currency", "paper": {}, "also": []}, {"id": "pak--the-fungible", "creator_ids": ["pak"], "title": "The Fungible", "year": 2021, "field": "onchain", "sub": "supply", "mechanisms": ["scarcity", "merge", "exchange"], "substrate": "ethereum", "kind": "series", "description": "Pak's sale with Sotheby's on Nifty Gateway (12–14 April 2021): identical 'cubes' were sold as an open edition for 15 minutes a day, and each buyer's cubes were then packed into NFTs whose image depends on how many they bought.", "description_zh": "Pak 与苏富比在 Nifty Gateway 上的发售（2021 年 4 月 12 日至 14 日）：完全相同的“方块”以开放版数每天只卖 15 分钟，之后每位买家的方块按购买数量打包成不同画面的 NFT。", "idea_en": "Sell a fungible unit and let the quantity each person buys decide which non-fungible artwork they end up holding.", "idea_zh": "卖的是可互换的单位，每人买多少决定他最后拿到哪件不可互换的作品。", "protocol": "Anyone could buy any number of cubes during a 15-minute window each day, at $500, then $1,000, then $1,500. After the sale each buyer's total was split into the largest possible packs: A Cube (1), Five, Ten, Twenty, Fifty, Hundred, Five Hundred and Thousand Cubes (six cubes = one Five Cubes + one A Cube). The top buyer received The Cube, the next 100 buyers received Complexity, and Equilibrium went to four winners of set challenges (puzzle, highest secondary purchase, largest #PakWasHere post, closest estimate of the total).", "protocol_zh": "每天 15 分钟的窗口内，任何人都可以买任意数量的方块，三天价格依次为 500、1000、1500 美元。发售结束后，每位买家的总数被拆成尽可能大的包：A Cube（1）、Five、Ten、Twenty、Fifty、Hundred、Five Hundred 和 Thousand Cubes（买六个 = 一个 Five Cubes 加一个 A Cube）。买得最多的人获得 The Cube，其后 100 人获得 Complexity；Equilibrium 的四个版本分别给解谜者、二级市场最高价买家、#PakWasHere 帖子受众最大者和最接近总成交额的预测者。", "collective": "Buyers took 19,737 cubes on day one, 3,268 on day two and 593 on day three: 23,598 cubes for about $14 million. With the two auctioned 1/1s (The Switch, The Pixel) the sale reached $16.8 million (Sotheby's). Many cube holders later burned their cubes on burn.art to mine ASH.", "collective_zh": "买家第一天买下 19,737 个方块，第二天 3,268 个，第三天 593 个，共 23,598 个，约 1,400 万美元。加上两件拍卖的单版作品（The Switch、The Pixel），整场销售额为 1,680 万美元（据苏富比）。许多方块持有者后来在 burn.art 上销毁方块以挖取 ASH。", "keywords": ["open edition", "Sotheby's", "Nifty Gateway", "cubes", "The Cube", "The Pixel", "The Switch"], "images": ["https://sothebys-com.brightspotcdn.com/06/07/900df8e0456599524176879a8a1e/cube-image.png", "https://sothebys-com.brightspotcdn.com/37/f3/895926734d5c955091dc1b526904/equillibrium.png"], "source_url": "https://www.sothebys.com/en/articles/17-million-realized-in-sothebys-first-nft-sale-with-digital-creator-pak", "contract_url": "https://etherscan.io/address/0xc7cc3e8c6b69dc272ccf64cbff4b7503cbf7c1c5", "video": {}, "paper": {}, "also": []}, {"id": "pak--burn-art-ash", "creator_ids": ["pak"], "title": "burn.art and $ASH", "year": 2021, "field": "onchain", "sub": "supply", "mechanisms": ["burn", "currency", "scarcity"], "substrate": "ethereum", "kind": "platform", "description": "A site where anyone can destroy an NFT and receive ASH, an ERC-20 token that started with zero supply and can only be mined by burning. ASH then became the only currency accepted for some Pak drops.", "description_zh": "一个任何人都可以在上面销毁 NFT、换取 ASH 的网站。ASH 是一种初始供应为零、只能靠销毁挖出的 ERC-20 代币，后来成为部分 Pak 发售唯一接受的货币。", "idea_en": "A currency backed by what its holders have destroyed: every burn makes the remaining works rarer.", "idea_zh": "一种以持有者销毁之物为支撑的货币：每销毁一件，剩下的就更稀少。", "protocol": "Any holder can burn an NFT on burn.art and receive newly minted ASH. The yield follows a bonding curve that falls as supply grows, with two tiers: Pak NFTs start at 1,000 ASH, all other NFTs at 2 ASH; a halving hits every tier at 5 million ASH. Liquidity pools are left to the community. From January 2022 (Chapter One: Carbon) some Pak drops could only be bought or bid on with ASH.", "protocol_zh": "任何持有者都可以在 burn.art 上销毁一件 NFT，换取新铸造的 ASH。产出按供应量递减的联合曲线计算，分两档：Pak 的 NFT 起始为 1000 ASH，其他 NFT 起始为 2 ASH；供应达到 500 万时所有档位减半。流动性池由社区自行建立。自 2022 年 1 月（Chapter One: Carbon）起，部分 Pak 发售只能用 ASH 购买或出价。", "collective": "Collectors burned their own and others' NFTs, above all Fungible cubes, to mine ASH; Carbon's single edition is titled 'Three Thousand Eight Hundred Twenty Five Burned Cubes', and only ASH holders could bid on it. By September 2026 the ASH contract showed about 3.54 million tokens held by about 9,950 addresses (Blockscout).", "collective_zh": "藏家销毁自己和他人的 NFT（尤其是 The Fungible 的方块）来挖 ASH；Carbon 的单版作品题为“Three Thousand Eight Hundred Twenty Five Burned Cubes”（三千八百二十五个被烧掉的方块），只有 ASH 持有者能出价。截至 2026 年 9 月，ASH 合约显示约 354 万枚代币，分布在约 9,950 个地址中（据 Blockscout）。", "keywords": ["ASH", "ERC-20", "burn", "bonding curve", "Carbon", "burn.art"], "images": ["https://burn.art/x.png", "https://burn.art/_next/static/media/burned-cubes.061a79ae.png", "https://burn.art/_next/static/media/carbon.143793db.png"], "source_url": "https://burn.art/about", "contract_url": "https://etherscan.io/address/0x64D91f12Ece7362F91A6f8E7940Cd55F05060b92", "video": {}, "paper": {}, "also": []}, {"id": "amy-whitaker--art-and-blockchain", "creator_ids": ["amy-whitaker"], "title": "Art and Blockchain: A Primer, History, and Taxonomy of Blockchain Use Cases in the Arts", "year": 2019, "field": "theory", "sub": "crypto-theory", "mechanisms": ["contract", "exchange", "currency"], "substrate": "text", "kind": "publication", "description": "Peer-reviewed article in Artivate (vol. 8, no. 2, 2019) that explains blockchain for arts readers, gives a history of its uses in art and sorts them into a taxonomy.", "description_zh": "发表于《Artivate》（第 8 卷第 2 期，2019）的同行评审论文，为艺术领域读者讲解区块链，梳理其在艺术中的应用历史，并建立分类。", "idea_en": "Blockchain can change who holds a stake in an artwork, not only how it is sold.", "idea_zh": "区块链改变的不只是作品如何出售，还有谁能在作品中持有份额。", "protocol": "Whitaker classifies use cases (provenance registries, fractional ownership, resale royalties, new funding structures) and discusses how they blur the line between for-profit and nonprofit support for art.", "protocol_zh": "Whitaker 对应用场景进行分类（来源登记、碎片化所有权、转售版税、新的资助结构），并讨论它们如何模糊营利与非营利艺术资助之间的界线。", "collective": "Published before the 2021 NFT boom, the article became an early scholarly reference for art-market and arts-management research on tokens and shared ownership.", "collective_zh": "这篇论文发表于 2021 年 NFT 热潮之前，成为艺术市场与艺术管理领域研究代币和共享所有权的早期学术参考。", "keywords": ["Artivate", "art market", "provenance", "fractional ownership", "resale royalties"], "images": ["https://artivate.org/public/journals/1/article_94_cover_en_US.png"], "paper": {"url": "https://artivate.org/index.php/artivate/article/view/94", "doi": "10.34053/artivate.8.2.2", "venue": "Artivate: A Journal of Entrepreneurship in the Arts 8, no. 2 (2019), pp. 21–46", "title": "Art and Blockchain: A Primer, History, and Taxonomy of Blockchain Use Cases in the Arts"}, "source_url": "https://artivate.org/index.php/artivate/article/view/94", "video": {}, "also": []}, {"id": "primavera-de-filippi--blockchain-and-the-law", "creator_ids": ["primavera-de-filippi", "aaron-wright"], "title": "Blockchain and the Law: The Rule of Code", "year": 2018, "field": "theory", "sub": "crypto-theory", "mechanisms": ["contract", "autonomy", "governance"], "substrate": "text", "kind": "publication", "description": "Book (Harvard University Press, 2018) on how blockchains let rules be written as self-executing code, a new order the authors call 'lex cryptographia', with chapters on smart contracts, DAOs and autonomous systems.", "description_zh": "一本书（哈佛大学出版社，2018），讨论区块链如何让规则以自动执行的代码形式存在，作者称之为“加密法”（lex cryptographia），各章涉及智能合约、DAO 与自治系统。", "idea_en": "When rules run as code, the code becomes a kind of law: design it as carefully as a constitution.", "idea_zh": "当规则以代码运行，代码就成了一种法律：要像设计宪法一样谨慎地设计它。", "protocol": "The authors explain how smart contracts enforce agreements without courts and how DAOs and autonomous agents can hold assets and act under code, and set out where this collides with existing law.", "protocol_zh": "作者解释智能合约如何在没有法院的情况下执行协议，DAO 与自治代理如何在代码之下持有资产和行动，并指出这些与现行法律的冲突之处。", "collective": "The book became a standard reference for law and governance of blockchain systems; De Filippi applies the same ideas in artworks such as Plantoid and in the Radical Friends anthology.", "collective_zh": "这本书成为区块链系统法律与治理的标准参考；De Filippi 也把同样的想法用于 Plantoid 等作品以及《Radical Friends》文集中。", "keywords": ["lex cryptographia", "smart contracts", "DAO", "code is law", "Harvard University Press"], "images": ["https://covers.openlibrary.org/b/isbn/9780674976429-L.jpg"], "paper": {"url": "https://www.hup.harvard.edu/books/9780674241596", "doi": "10.4159/9780674985933", "venue": "Harvard University Press, 2018", "title": "Blockchain and the Law: The Rule of Code"}, "source_url": "https://www.hup.harvard.edu/books/9780674241596", "video": {}, "also": []}, {"id": "ruth-catlow--artists-rethinking-the-blockchain", "creator_ids": ["ruth-catlow", "marc-garrett"], "title": "Artists Re:Thinking the Blockchain", "year": 2017, "field": "theory", "sub": "crypto-theory", "mechanisms": ["currency", "contract", "governance"], "substrate": "text", "kind": "publication", "description": "Anthology edited by Ruth Catlow, Marc Garrett, Nathan Jones and Sam Skinner (Torque Editions with Furtherfield and FACT, 2017), the first book on what blockchain technologies mean for art production and distribution.", "description_zh": "由 Ruth Catlow、Marc Garrett、Nathan Jones 和 Sam Skinner 主编的文集（Torque Editions 联合 Furtherfield 与 FACT，2017），是第一本讨论区块链技术对艺术生产与传播意味着什么的书。", "idea_en": "Ask what a blockchain could do for art beyond selling it: new rules for value, ownership and cooperation.", "idea_zh": "问问区块链除了卖艺术还能做什么：为价值、所有权与合作制定新规则。", "protocol": "The editors commissioned artists and researchers over a 12-month process to test blockchains as a medium; the book's companion interface, Finbook, let readers and bots trade on the value of its chapters.", "protocol_zh": "编者用 12 个月时间委托艺术家和研究者，把区块链当作媒介来测试；配套界面 Finbook 让读者和机器人对书中各章的价值进行交易。", "collective": "Contributors included Rhea Myers, Primavera De Filippi and Jaya Klara Brekke; a free digital edition was launched at Transmediale in February 2018, and the book seeded Furtherfield's DAO research that led to Radical Friends.", "collective_zh": "撰稿人包括 Rhea Myers、Primavera De Filippi 和 Jaya Klara Brekke；免费电子版于 2018 年 2 月在 Transmediale 发布，这本书也开启了 Furtherfield 此后通向《Radical Friends》的 DAO 研究。", "keywords": ["Furtherfield", "FACT", "Torque Editions", "Finbook", "blockchain art"], "images": ["https://torquetorque.net/wp-content/uploads/IMG_2370.jpg"], "paper": {"url": "https://torquetorque.net/publications/artists-rethinking-the-blockchain/", "venue": "Torque Editions / Furtherfield / FACT, Liverpool, 2017", "title": "Artists Re:Thinking the Blockchain"}, "source_url": "https://www.furtherfield.org/artists-rethinking-blockchain/", "video": {}, "also": []}, {"id": "mitchell-f-chan--digital-zones", "creator_ids": ["mitchell-f-chan"], "title": "Digital Zones of Immaterial Pictorial Sensibility", "year": 2017, "field": "onchain", "sub": "provenance", "mechanisms": ["burn", "contract", "scarcity"], "substrate": "ethereum", "kind": "artwork", "description": "An ERC-20 token work deployed on 29 August 2017 and unveiled at InterAccess, Toronto. It restages Yves Klein's Zones of Immaterial Pictorial Sensibility, including a ritual any holder can perform to destroy their token.", "description_zh": "2017 年 8 月 29 日部署、在多伦多 InterAccess 首次展出的 ERC-20 代币作品。它重演伊夫·克莱因的《非物质绘画感性区域》，包括任何持有者都能执行、销毁自己代币的仪式。", "idea_en": "Put an artist's sale ritual in a contract: buyers must deal with the contract directly, and 'owning the immaterial' means burning the receipt.", "idea_zh": "把艺术家的出售仪式写进合约：买家必须直接与合约打交道，“拥有非物质”意味着烧掉收据。", "protocol": "IKB is sold only by calling the contract's buy() function (no front end, on purpose). Supply is capped at 101 tokens in 8 series: Series 0 has 31 tokens at 0.1 ETH, each later series 10 tokens at double the previous price, with later series meant to be released over the artist's lifetime. Every sale is recorded per edition. A holder may call ritual(): the token is burned and half the ETH paid for it is sent to a separate contract called theRiver, echoing Klein throwing half the gold into the Seine.", "protocol_zh": "IKB 只能通过直接调用合约的 buy() 函数购买（刻意不做前端）。总量上限 101 枚，分 8 个系列：第 0 系列 31 枚、每枚 0.1 ETH，之后每个系列 10 枚、价格翻倍，后续系列按计划在艺术家一生中陆续发行。每次出售都按版次记录。持有者可调用 ritual()：代币被销毁，买它所付 ETH 的一半被转入名为 theRiver 的另一个合约，呼应克莱因把一半黄金抛入塞纳河。", "collective": "All Series 0 tokens sold out (artist's README, 2021); buyers had to work out how to call the contract by hand. The contract records each edition's buyer, price and whether it has been ritually burned.", "collective_zh": "第 0 系列全部售罄（艺术家 2021 年的说明）；买家必须自己弄清如何手动调用合约。合约记录了每个版次的买家、价格以及是否已被仪式销毁。", "keywords": ["IKB", "Yves Klein", "ritual", "ERC-20", "theRiver", "InterAccess", "Blue Paper"], "images": ["https://raw.githubusercontent.com/mitchellfchan/IKB/master/IKB_logo.png"], "paper": {"url": "https://github.com/mitchellfchan/IKB/blob/master/Digital-Zones-Of-Immaterial-Pictorial-Sensibility-Blue-Paper.pdf", "doi": "", "arxiv": "", "venue": "Artist whitepaper", "title": "The Blue Paper"}, "source_url": "https://github.com/mitchellfchan/IKB", "contract_url": "https://etherscan.io/address/0x88ae96845e157558ef59e9ff90e766e22e480390", "code_url": "https://github.com/mitchellfchan/IKB", "video": {}, "also": []}, {"id": "hans-ulrich-obrist--do-it-compendium", "creator_ids": ["hans-ulrich-obrist"], "title": "do it: the compendium", "year": 2013, "field": "theory", "sub": "participation", "also": ["score"], "mechanisms": ["instruction", "participation", "co-authorship"], "substrate": "text", "kind": "publication", "description": "Book (Independent Curators International and D.A.P., 2013) collecting twenty years of the do it exhibition, begun in Paris in 1993, in which artists write instructions that institutions and readers carry out.", "description_zh": "一本书（独立策展人国际与 D.A.P.，2013），汇集始于 1993 年巴黎的展览 do it 二十年的成果：艺术家写下指令，由机构和读者执行。", "idea_en": "An exhibition can travel as a set of instructions and be remade differently each time.", "idea_zh": "展览可以作为一组指令流动，每次都以不同方式被重新制作。", "protocol": "Each artist contributes a written instruction; any host may realise it with local means, and each realisation counts as a version of the work, not a copy.", "protocol_zh": "每位艺术家提供一条书面指令；任何主办方都可以用本地条件实现它，每次实现都算作作品的一个版本，而不是复制品。", "collective": "The compendium prints instructions by 250 artists, 84 of them newly published for the 20th anniversary, together with essays and documentation of past iterations staged by institutions around the world.", "collective_zh": "该书收录了 250 位艺术家的指令，其中 84 条为二十周年新发表，另附文章以及世界各地机构历次实施的记录。", "keywords": ["do it", "instructions", "exhibition format", "Independent Curators International", "Christian Boltanski"], "images": ["https://curatorsintl.org/images/doit_productshot.jpg?w=1600", "https://covers.openlibrary.org/b/isbn/9781938922015-L.jpg"], "paper": {"url": "https://curatorsintl.org/shop/15810-do-it-the-compendium", "venue": "Independent Curators International / D.A.P., 2013", "title": "do it: the compendium"}, "source_url": "https://www.artbook.com/9781938922015.html", "video": {}}, {"id": "claire-bishop--artificial-hells", "creator_ids": ["claire-bishop"], "title": "Artificial Hells: Participatory Art and the Politics of Spectatorship", "year": 2012, "field": "theory", "sub": "participation", "mechanisms": ["participation", "constraint"], "substrate": "text", "kind": "publication", "description": "Book (Verso, 2012) that gives the first historical and theoretical overview of socially engaged participatory art, from Futurist evenings and Situationism to 1960s happenings and recent social practice.", "description_zh": "一本书（Verso，2012），首次对社会介入式参与艺术做了历史与理论的全面梳理：从未来主义之夜、情境主义到 1960 年代偶发艺术和近年的社会实践。", "idea_en": "Judge a participatory work by the tensions its rules create, not only by how nice the collaboration feels.", "idea_zh": "评价参与式作品，要看它的规则制造了怎样的张力，而不只看合作是否愉快。", "protocol": "Bishop analyses how artists 'delegate' performance and set rules for participants, and argues against judging such work only by its ethics; the best works keep a productive discomfort between author and participants.", "protocol_zh": "Bishop 分析艺术家如何“委托”表演、为参与者设定规则，并反对只从伦理角度评价此类作品；她认为最好的作品会在作者与参与者之间保持一种有生产性的不适。", "collective": "The book shaped a decade of debate on social practice and is widely taught; its account of delegated performance applies directly to works where crowds act under an artist's rules.", "collective_zh": "这本书塑造了此后十年关于社会实践的讨论，被广泛用于教学；其关于“委托表演”的论述，直接适用于人群在艺术家规则下行动的作品。", "keywords": ["social practice", "delegated performance", "spectatorship", "Verso", "participatory art"], "images": ["https://www.versobooks.com/cdn/shop/files/getimage_10a3d3bd-a97c-44a2-85dd-b57c2d53fcbc.jpg?v=1790568936"], "paper": {"url": "https://www.versobooks.com/products/2251-artificial-hells", "venue": "Verso, London and New York, 2012", "title": "Artificial Hells: Participatory Art and the Politics of Spectatorship"}, "source_url": "https://www.versobooks.com/products/2251-artificial-hells", "video": {}, "also": []}, {"id": "alexander-galloway--the-exploit", "creator_ids": ["alexander-galloway", "eugene-thacker"], "title": "The Exploit: A Theory of Networks", "year": 2007, "field": "theory", "sub": "systems", "mechanisms": ["constraint", "governance"], "substrate": "text", "kind": "publication", "description": "Book (University of Minnesota Press, 2007) arguing that networks create their own forms of control, both centralised and dispersed, and that resistance must work through 'exploits': holes found inside the protocol itself.", "description_zh": "一本书（明尼苏达大学出版社，2007），认为网络会产生自身特有的控制形式，既集中又分散；抵抗必须通过“漏洞利用”进行，也就是在协议内部找到的缺口。", "idea_en": "To change a network, use its own rules against it.", "idea_zh": "要改变一个网络，就用它自己的规则反过来对付它。", "protocol": "The authors describe networks as topologies governed by protocol, and the exploit as a practice that follows the rules exactly while turning them to unintended ends.", "protocol_zh": "作者把网络描述为由协议支配的拓扑结构，而“漏洞利用”是一种严格遵守规则、却把规则引向意外用途的实践。", "collective": "The book gave hacktivists, tactical-media groups and software artists a vocabulary for working inside network protocols rather than outside them.", "collective_zh": "这本书为黑客行动者、战术媒体团体和软件艺术家提供了一套在网络协议内部、而非外部工作的词汇。", "keywords": ["networks", "exploit", "hacking", "biopolitics", "Electronic Mediations"], "images": ["https://covers.openlibrary.org/b/isbn/9780816650446-L.jpg"], "paper": {"url": "https://www.upress.umn.edu/book-division/books/the-exploit", "venue": "University of Minnesota Press, Electronic Mediations 21, 2007", "title": "The Exploit: A Theory of Networks"}, "source_url": "https://www.upress.umn.edu/book-division/books/the-exploit", "video": {}, "also": []}, {"id": "claire-bishop--participation", "creator_ids": ["claire-bishop"], "title": "Participation", "year": 2006, "field": "theory", "sub": "participation", "mechanisms": ["participation", "instruction"], "substrate": "text", "kind": "publication", "description": "Anthology edited by Bishop (Whitechapel Gallery and MIT Press, Documents of Contemporary Art, 2006) that collects theory, artists' statements and curatorial debates on art that makes spectators into participants.", "description_zh": "Bishop 主编的文集（白教堂画廊与 MIT Press 合作的“当代艺术文献”丛书，2006），收录关于“让观众成为参与者”之艺术的理论、艺术家文本与策展辩论。", "idea_en": "Participation has a history and a theory: read the rules artists wrote for audiences side by side.", "idea_zh": "参与有它的历史和理论：把艺术家为观众写下的规则放在一起读。", "protocol": "The book gathers texts in which artists define what participants may do, from Lygia Clark, Hélio Oiticica and Joseph Beuys to Thomas Hirschhorn and Rirkrit Tiravanija, next to theory by Eco, Barthes, Rancière and Guattari.", "protocol_zh": "书中汇集了艺术家界定参与者可以做什么的文本，从 Lygia Clark、Hélio Oiticica、Joseph Beuys 到 Thomas Hirschhorn、Rirkrit Tiravanija，并与 Eco、Barthes、Rancière、Guattari 的理论并置。", "collective": "It became a standard course reader on participatory art and included the first English translation of Rancière's 'Problems and Transformations in Critical Art'.", "collective_zh": "它成为参与式艺术课程的标准读本，并收录了 Rancière《批判艺术的问题与转变》的第一个英译本。", "keywords": ["participatory art", "Whitechapel", "Documents of Contemporary Art", "Rancière", "anthology"], "images": ["https://covers.openlibrary.org/b/isbn/9780262524643-L.jpg"], "paper": {"url": "https://shop.whitechapelgallery.org/products/participation", "venue": "Whitechapel Gallery / MIT Press, 2006", "title": "Participation"}, "source_url": "https://shop.whitechapelgallery.org/products/participation", "video": {}, "also": []}, {"id": "florian-cramer--words-made-flesh", "creator_ids": ["florian-cramer"], "title": "Words Made Flesh: Code, Culture, Imagination", "year": 2005, "field": "theory", "sub": "systems", "mechanisms": ["instruction", "constraint"], "substrate": "text", "kind": "publication", "description": "Book-length essay written at the Piet Zwart Institute in Rotterdam and published online in 2005, tracing the idea of executable language from magic and combinatory poetry to Fluxus scores and computer code.", "description_zh": "在鹿特丹 Piet Zwart Institute 写成、2005 年在网上发表的长篇论文，追溯“可执行语言”的观念：从魔法和组合诗歌到激浪派乐谱和计算机代码。", "idea_en": "A score, a spell and a program share one property: words that make things happen when executed.", "idea_zh": "乐谱、咒语和程序有一个共同点：它们是被执行时会让事情发生的文字。", "protocol": "Cramer shows that instructions have a long cultural history outside computing, and that the same text can be read as description or run as action, by people or by machines.", "protocol_zh": "Cramer 指出，指令在计算之外有很长的文化历史；同一段文本既可以被当作描述来读，也可以被人或机器当作行动来执行。", "collective": "Distributed free online and through the Internet Archive, the text became a common reference in software-art and code-poetry teaching.", "collective_zh": "该文本通过网络和互联网档案馆免费流通，成为软件艺术和代码诗歌教学中常用的参考文献。", "keywords": ["software art", "executable code", "Fluxus", "combinatory poetry", "Piet Zwart Institute"], "images": ["https://archive.org/services/img/WordsMadeFlesh"], "paper": {"url": "https://archive.org/details/WordsMadeFlesh", "venue": "Piet Zwart Institute, Rotterdam, 2005", "title": "Words Made Flesh: Code, Culture, Imagination"}, "source_url": "https://www.netzliteratur.net/cramer/wordsmadefleshpdf.pdf", "video": {}, "also": []}, {"id": "grant-kester--conversation-pieces", "creator_ids": ["grant-kester"], "title": "Conversation Pieces: Community and Communication in Modern Art", "year": 2004, "field": "theory", "sub": "participation", "mechanisms": ["participation", "co-authorship"], "substrate": "text", "kind": "publication", "description": "Book (University of California Press, 2004) on 'dialogical' art, where artists set up long-term exchanges with communities and the conversation itself becomes the work.", "description_zh": "一本书（加州大学出版社，2004），讨论“对话性”艺术：艺术家与社区建立长期交流，交流本身成为作品。", "idea_en": "Design the conversation, not the object: the work is what people say and decide together.", "idea_zh": "设计的是对话而非物件：作品就是人们共同说出和决定的内容。", "protocol": "Kester describes projects in which the artist frames a dialogue among groups that rarely meet (for example officials, workers and residents) and the outcome is decided in that exchange.", "protocol_zh": "Kester 描述了这样的项目：艺术家为很少相遇的群体（例如官员、劳动者和居民）搭建对话框架，结果在交流中决定。", "collective": "The book, reissued in an updated edition in 2013, became a key reference for collaborative and community-based art, offering an alternative to judging such work by its visual form.", "collective_zh": "该书于 2013 年推出增订版，成为协作式与社区艺术的重要参考，提供了一种不以视觉形式评判此类作品的思路。", "keywords": ["dialogical art", "community art", "collaboration", "UC Press", "WochenKlausur"], "images": ["https://covers.openlibrary.org/b/isbn/9780520238398-L.jpg"], "paper": {"url": "https://www.ucpress.edu/books/conversation-pieces/paper", "venue": "University of California Press, 2004", "title": "Conversation Pieces: Community and Communication in Modern Art"}, "source_url": "https://www.ucpress.edu/books/conversation-pieces/paper", "video": {}, "also": []}, {"id": "alexander-galloway--protocol", "creator_ids": ["alexander-galloway"], "title": "Protocol: How Control Exists after Decentralization", "year": 2004, "field": "theory", "sub": "systems", "mechanisms": ["constraint", "governance"], "substrate": "text", "kind": "publication", "description": "Book (MIT Press, 2004) arguing that the internet is organised not by freedom but by protocols such as TCP/IP and DNS, which distribute control into technical standards; it also discusses net art and hacking as practices that work inside protocol.", "description_zh": "一本书（MIT Press，2004），认为互联网并非由自由组织，而是由 TCP/IP、DNS 等协议组织，控制被分散到技术标准之中；书中也讨论了在协议内部工作的网络艺术与黑客实践。", "idea_en": "Protocol is how control works when there is no centre: design the protocol and you design the behaviour.", "idea_zh": "协议是没有中心时控制的运作方式：设计协议，就是设计行为。", "protocol": "Galloway defines protocol as a set of voluntary technical rules that every node must follow to connect; its power lies in making behaviour standard while leaving each node apparently free.", "protocol_zh": "Galloway 把协议定义为每个节点为了连接都必须遵守的一组自愿技术规则；它的力量在于让行为标准化，同时让每个节点看起来是自由的。", "collective": "The book became the main theory text for net art, tactical media and later crypto and protocol art, and is cited by artists who treat standards and smart contracts as their medium.", "collective_zh": "这本书成为网络艺术、战术媒体以及后来加密与协议艺术的主要理论文本，被把标准和智能合约当作媒介的艺术家广泛引用。", "keywords": ["protocol", "TCP/IP", "control society", "net art", "tactical media"], "images": ["https://covers.openlibrary.org/b/isbn/9780262072472-L.jpg"], "paper": {"url": "https://direct.mit.edu/books/book/2528/ProtocolHow-Control-Exists-after-Decentralization", "doi": "10.7551/mitpress/5658.001.0001", "venue": "MIT Press, Leonardo Book Series, 2004", "title": "Protocol: How Control Exists after Decentralization"}, "source_url": "https://direct.mit.edu/books/book/2528/ProtocolHow-Control-Exists-after-Decentralization", "video": {}, "also": []}, {"id": "nicolas-bourriaud--relational-aesthetics", "creator_ids": ["nicolas-bourriaud"], "title": "Relational Aesthetics", "year": 1998, "field": "theory", "sub": "participation", "mechanisms": ["participation", "exchange"], "substrate": "text", "kind": "publication", "description": "Book first published in French as Esthétique relationnelle (Les presses du réel, 1998; English 2002) that describes 1990s art whose material is human relations: shared meals, meetings, services and temporary social spaces.", "description_zh": "一本书，法文原版《Esthétique relationnelle》由 Les presses du réel 于 1998 年出版（英文版 2002 年），描述 1990 年代以人际关系为材料的艺术：共餐、聚会、服务和临时社交空间。", "idea_en": "The artwork can be a situation: a set of conditions under which people meet and interact.", "idea_zh": "作品可以是一个情境：一组让人们相遇和互动的条件。", "protocol": "Bourriaud describes artworks as 'social interstices': the artist sets up a situation with loose rules of use, and visitors complete it by how they gather, eat, talk or exchange.", "protocol_zh": "Bourriaud 把作品描述为“社会间隙”：艺术家设定一个带有宽松使用规则的情境，观众通过聚集、进食、交谈或交换的方式完成它。", "collective": "The book named a generation (Rirkrit Tiravanija, Liam Gillick, Philippe Parreno and others) and became one of the most cited and most debated texts on participatory art.", "collective_zh": "这本书命名了一代艺术家（Rirkrit Tiravanija、Liam Gillick、Philippe Parreno 等），成为参与式艺术领域被引用和争论最多的文本之一。", "keywords": ["relational aesthetics", "Rirkrit Tiravanija", "social interstice", "1990s", "Les presses du réel"], "images": ["https://covers.openlibrary.org/b/isbn/9782840660606-L.jpg", "https://www.lespressesdureel.com/EN/img/ouvrage/12797/_f.jpg"], "paper": {"url": "https://www.lespressesdureel.com/EN/ouvrage.php?id=12797&menu=0", "venue": "Les presses du réel, Dijon, 1998", "title": "Esthétique relationnelle / Relational Aesthetics"}, "source_url": "https://www.lespressesdureel.com/EN/ouvrage.php?id=12762&menu=0", "video": {}, "also": []}, {"id": "benjamin-buchloh--aesthetic-of-administration", "creator_ids": ["benjamin-buchloh"], "title": "Conceptual Art 1962–1969: From the Aesthetic of Administration to the Critique of Institutions", "year": 1990, "field": "theory", "sub": "systems", "also": ["social"], "mechanisms": ["contract", "instruction"], "substrate": "text", "kind": "publication", "description": "Essay in October (Winter 1990) that reads Conceptual art through its use of administrative forms: certificates, statements, lists, legal contracts and instructions.", "description_zh": "发表于《October》（1990 年冬季号）的文章，从行政形式的角度解读观念艺术：证书、声明、清单、法律契约与指令。", "idea_en": "Paperwork is a medium: certificates and contracts can carry the whole work.", "idea_zh": "文书本身就是媒介：证书和契约可以承载整件作品。", "protocol": "Buchloh argues that artists such as LeWitt, Kosuth, Weiner and Haacke replaced craft with the procedures of bureaucracy, so that the work consists of rules, documents and institutional relations.", "protocol_zh": "Buchloh 认为 LeWitt、Kosuth、Weiner 和 Haacke 等艺术家以官僚程序取代了手艺，作品因此由规则、文件和机构关系构成。", "collective": "The essay framed later readings of certificates, receipts and artist contracts as art, the lineage that curators and writers now connect to smart-contract art.", "collective_zh": "这篇文章影响了后来把证书、收据和艺术家契约视为艺术的解读，策展人和作者如今把这一脉络与智能合约艺术联系起来。", "keywords": ["Conceptual art", "October", "institutional critique", "certificates", "administration"], "paper": {"url": "https://www.jstor.org/stable/778941", "doi": "10.2307/778941", "venue": "October 55 (Winter 1990), MIT Press", "title": "Conceptual Art 1962–1969: From the Aesthetic of Administration to the Critique of Institutions"}, "source_url": "https://doi.org/10.2307/778941", "video": {}, "images": []}, {"id": "roy-ascott--telematic-embrace", "creator_ids": ["roy-ascott"], "title": "Is There Love in the Telematic Embrace?", "year": 1990, "field": "theory", "sub": "systems", "also": ["network"], "mechanisms": ["participation", "co-authorship", "circulation"], "substrate": "text", "kind": "publication", "description": "Essay in Art Journal (Autumn 1990) in which Ascott describes telematic art: works made by many participants linked through computer networks, with meaning produced in their exchanges.", "description_zh": "发表于《Art Journal》（1990 年秋季号）的文章。Ascott 在其中描述远程通信艺术：由通过计算机网络相连的众多参与者共同完成、意义在其交流中产生的作品。", "idea_en": "On a network, authorship is distributed: the artist sets up the link, the participants make the work.", "idea_zh": "在网络上，作者身份是分布式的：艺术家搭建连接，参与者完成作品。", "protocol": "The artist provides a networked context and a few rules for contribution; participants at distant nodes add, transform and pass on material, and no single author controls the result.", "protocol_zh": "艺术家提供一个网络化的情境和少量参与规则；远方节点上的参与者添加、改写并传递素材，没有哪个单一作者能控制结果。", "collective": "The essay draws on Ascott's own networked projects, such as La Plissure du Texte (1983), in which participants in several cities wrote a fairy tale together; it became a founding text for telematic and net art and titles his collected writings, Telematic Embrace (2003).", "collective_zh": "文章基于 Ascott 自己的网络项目，例如 La Plissure du Texte（1983），多个城市的参与者在其中共同写作一则童话；它成为远程通信艺术与网络艺术的奠基文本，也成为他文集《Telematic Embrace》（2003）的书名。", "keywords": ["telematic art", "distributed authorship", "Art Journal", "networks", "La Plissure du Texte"], "images": ["https://covers.openlibrary.org/b/isbn/9780520222946-L.jpg"], "paper": {"url": "https://www.jstor.org/stable/777114", "doi": "10.1080/00043249.1990.10792697", "venue": "Art Journal 49, no. 3 (Autumn 1990), pp. 241–247", "title": "Is There Love in the Telematic Embrace?"}, "source_url": "https://doi.org/10.1080/00043249.1990.10792697", "video": {}}, {"id": "jack-burnham--software", "creator_ids": ["jack-burnham"], "title": "Software: Information Technology: Its New Meaning for Art", "year": 1970, "field": "theory", "sub": "systems", "mechanisms": ["instruction", "participation"], "substrate": "text", "kind": "publication", "description": "Exhibition and catalogue curated by Burnham at the Jewish Museum, New York (16 September – 8 November 1970), that showed conceptual artists and computer systems side by side, treating 'software' as instructions carried out by machines or by visitors.", "description_zh": "Burnham 在纽约犹太博物馆策划的展览及其画册（1970 年 9 月 16 日至 11 月 8 日），把观念艺术家与计算机系统并置，把“软件”理解为由机器或观众执行的指令。", "idea_en": "An exhibition can be a program: instructions that visitors and machines execute together.", "idea_zh": "展览本身可以是一段程序：由观众和机器共同执行的指令。", "protocol": "Works were framed as 'software': sets of instructions written by the artist and run by a computer or by the public, such as Hans Haacke's Visitor's Profile, which tabulated visitors' answers to a questionnaire, and Ted Nelson's hypertext catalogue Labyrinth.", "protocol_zh": "作品被当作“软件”来呈现：由艺术家写下、由计算机或公众执行的指令组，例如 Hans Haacke 的 Visitor's Profile（统计观众填写的问卷）和 Ted Nelson 的超文本目录 Labyrinth。", "collective": "Visitors' answers and actions supplied the content of several works; the show, which also travelled to the Smithsonian, is remembered as the first major US museum exhibition to bring the computer into the gallery.", "collective_zh": "观众的回答和操作构成了多件作品的内容；该展随后巡回至史密森尼学会，被视为美国第一个把计算机带进展厅的大型博物馆展览。", "keywords": ["Jewish Museum", "1970", "Hans Haacke", "Ted Nelson", "information art"], "images": ["https://monoskop.org/images/5/5b/Software-catalogue.jpg"], "paper": {"url": "https://monoskop.org/Software_(exhibition)", "venue": "The Jewish Museum, New York, 1970 (exhibition catalogue)", "title": "Software: Information Technology: Its New Meaning for Art"}, "source_url": "https://www.fondation-langlois.org/html/e/page.php?NumPage=541", "video": {}, "also": []}, {"id": "sol-lewitt--sentences-on-conceptual-art", "creator_ids": ["sol-lewitt"], "title": "Sentences on Conceptual Art", "year": 1969, "field": "theory", "sub": "systems", "also": ["score"], "mechanisms": ["instruction", "constraint"], "substrate": "text", "kind": "publication", "description": "Thirty-five numbered statements first printed in the magazine 0 to 9 (no. 5, January 1969) and then in the first issue of Art-Language (May 1969), extending LeWitt's argument that ideas alone can be works of art.", "description_zh": "三十五条编号语句，首先刊于杂志《0 to 9》第 5 期（1969 年 1 月），随后刊于《Art-Language》创刊号（1969 年 5 月），延续了 LeWitt“观念本身即可成为艺术作品”的论点。", "idea_en": "Once the process is set, let it run: follow the rules even when the result surprises you.", "idea_zh": "过程一旦设定就让它运行：即使结果出乎意料，也按规则走下去。", "protocol": "The sentences state that the artist should not change the idea mid-course, that the process is mechanical once begun, and that 'the idea becomes a machine that makes the art'; perception of the work is left to each viewer.", "protocol_zh": "这些语句规定：艺术家不应在中途改变观念；过程一旦开始便是机械的；“观念成为制造艺术的机器”；对作品的感知则留给每位观者。", "collective": "Reprinted in most Conceptual art anthologies, the sentences are read as a rulebook by artists who write systems for others to run, from wall-drawing assistants to generative and smart-contract artists.", "collective_zh": "这组语句被大多数观念艺术文集收录，被那些为他人编写可执行系统的艺术家当作规则手册来读：从墙绘助手到生成艺术和智能合约艺术家。", "keywords": ["Conceptual art", "0 to 9", "Art-Language", "rules", "process"], "images": ["https://wiels.org/uploads/resized/uploads/355769/Sol-LeWitts-Sentences-on-Conceptual-Art-Manuscript-and-Draft-Material-196869_58f02840803f2ddfa28c8dbfb30a044c.jpg"], "paper": {"url": "https://monoskop.org/images/3/3d/LeWitt_Sol_1969_1999_Sentences_on_Conceptual_Art.pdf", "venue": "0 to 9, no. 5 (January 1969); Art-Language 1, no. 1 (May 1969)", "title": "Sentences on Conceptual Art"}, "source_url": "https://wiels.org/en/events/sol-lewitts-sentences-on-conceptual-art-manuscript-and-draft-material-1968-69", "video": {}}, {"id": "jack-burnham--systems-esthetics", "creator_ids": ["jack-burnham"], "title": "Systems Esthetics", "year": 1968, "field": "theory", "sub": "systems", "mechanisms": ["constraint", "participation"], "substrate": "text", "kind": "publication", "description": "Essay in Artforum (September 1968) arguing that art was shifting from making objects to organising systems: relations between people, materials, information and institutions over time.", "description_zh": "发表于《Artforum》（1968 年 9 月）的文章，认为艺术正从制造物体转向组织系统：人、材料、信息与机构之间随时间变化的关系。", "idea_en": "The artwork is not the object but the system of relations it sets in motion.", "idea_zh": "作品不是物体，而是它所启动的关系系统。", "protocol": "Burnham borrows from systems theory and cybernetics: a work is a set of components and the rules of their interaction, and the artist designs those relations instead of a finished form.", "protocol_zh": "Burnham 借用系统论和控制论：作品是一组组成部分及其相互作用的规则，艺术家设计的是这些关系，而不是一个完成的形式。", "collective": "The essay gave critics and artists (Hans Haacke among them) a language for process, ecological and information-based work, and is now a standard reference for software, network and protocol art.", "collective_zh": "这篇文章为评论家和艺术家（包括 Hans Haacke）提供了讨论过程、生态与信息类作品的语言，如今是软件、网络与协议艺术的标准参考文献。", "keywords": ["systems theory", "cybernetics", "post-formalism", "Artforum", "Hans Haacke"], "images": ["https://www.artforum.com/wp-content/uploads/2012/08/article00_large-23.jpg"], "paper": {"url": "https://www.artforum.com/features/systems-esthetics-201372/", "venue": "Artforum 7, no. 1 (September 1968), pp. 30–35", "title": "Systems Esthetics"}, "source_url": "https://www.artforum.com/features/systems-esthetics-201372/", "video": {}, "also": []}, {"id": "sol-lewitt--paragraphs-on-conceptual-art", "creator_ids": ["sol-lewitt"], "title": "Paragraphs on Conceptual Art", "year": 1967, "field": "theory", "sub": "systems", "also": ["score"], "mechanisms": ["instruction", "constraint"], "substrate": "text", "kind": "publication", "description": "Essay published in the Summer 1967 issue of Artforum in which LeWitt defines Conceptual art: the idea is the most important part of the work, and its execution follows a plan fixed in advance.", "description_zh": "1967 年夏季号《Artforum》上发表的文章。LeWitt 在其中界定观念艺术：观念是作品最重要的部分，执行只是按照事先确定的计划进行。", "idea_en": "Write the plan first; once it exists, the idea becomes a machine that makes the art.", "idea_zh": "先写下计划；计划一旦存在，观念就成了制造艺术的机器。", "protocol": "All planning and decisions are made beforehand and 'the execution is a perfunctory affair'; the artist fixes a premise and a system, and anyone following it produces the work without new aesthetic choices.", "protocol_zh": "所有计划和决定都事先完成，“执行只是例行公事”；艺术家确定前提和系统，任何人照做都能完成作品，无需再做审美选择。", "collective": "The text became the working manifesto for instruction-based practice: LeWitt's own wall drawings are still executed by drafters and museum teams from his written instructions, and later instruction, score and code-based artists cite it as a starting point.", "collective_zh": "这篇文章成为指令式创作的工作宣言：LeWitt 自己的墙绘至今仍由绘图员和博物馆团队根据他的书面指令执行，后来的指令、乐谱与代码艺术家也常以它为起点。", "keywords": ["Conceptual art", "Artforum", "instructions", "idea as machine", "wall drawings"], "images": ["https://www.artforum.com/wp-content/uploads/2018/04/article00_large-51.jpg"], "paper": {"url": "https://www.artforum.com/features/paragraphs-on-conceptual-art-211354/", "venue": "Artforum 5, no. 10 (Summer 1967)", "title": "Paragraphs on Conceptual Art"}, "source_url": "https://www.artforum.com/features/paragraphs-on-conceptual-art-211354/", "video": {}}]};
